import { Subject } from 'rxjs';
import type { LoggerStore } from '../logger';
import type { EvalEntry } from '../interfaces';
import { getActiveColor } from './fen';

//const debugging = true;

const regexBestMove = /^bestmove\s+(\S+)/;

const MATE_SCORE = 100;

type OperationType = 'initialize' | 'inf_calc' | 'best_move';

// interface iOperation {
//   handleWorkerMessage(line: string): boolean;
//   done: Promise<unknown>;
//   tryCancel(): void;
// }

abstract class Operation {
  public static __sequence = 0; // static counter shared across all subclasses

  public readonly sequence: number;

  //return true if done
  abstract handleWorkerMessage(line: string): boolean;

  abstract readonly type: OperationType;

  constructor(protected postMessage: (line: string) => void) {
    Operation.__sequence += 1;

    this.sequence = Operation.__sequence;
  }

  abstract start(): void;

  abstract tryCancel(): void;

  protected resolve!: (v: void) => void;
  protected reject!: (e: unknown) => void;

  readonly done = new Promise<void>((res, rej) => {
    this.resolve = res;
    this.reject = rej;
  });
}

class InitOperation extends Operation {
  tryCancel(): void {
    //do nothing
  }
  handleWorkerMessage(line: string): boolean {
    //console.log(`ready ${line}`);
    if (line == 'uciok') {
      this.resolve();
      return true;
    }
    return false;
  }
  type: OperationType = 'initialize';

  start() {
    this.postMessage('uci');
  }
}

class BestMoveOperation extends Operation {
  public lastEval: Thinking | null = null;
  public uci: string | null = null;

  handleWorkerMessage(line: string): boolean {
    //    console.log(`Best move message ${line}`);
    if (line.includes('score')) {
      const newScore = parseThinkingLine(line);
      if (newScore != null) {
        this.lastEval = newScore;
        if (!this.isWhite) {
          this.lastEval.score *= -1;
        }
      }
      return false;
    }

    const match = line.match(regexBestMove);

    if (!match) {
      return false;
    }

    const bestmove = match[1]!; // "g8h8"
    this.uci = bestmove;
    this.resolve();
    return true;
  }
  type: OperationType = 'best_move';
  isWhite: boolean;

  constructor(
    private fen: string,
    private calcTimeSec: number,
    postMessage: (line: string) => void,
  ) {
    super(postMessage);
    this.isWhite = getActiveColor(this.fen) == 'w';
  }

  start(): void {
    console.debug(`Posting best move ${this.fen} ${this.calcTimeSec}`);
    this.postMessage('setoption name MultiPV value 1');
    this.postMessage(`position fen ${this.fen}`);

    const calcTimeMs = Math.round(1000 * this.calcTimeSec);

    this.postMessage(`go movetime ${calcTimeMs}`);
  }
  tryCancel(): void {
    console.log('try cancel best move');
    this.postMessage('stop');
  }
}

class InfiniteAnalysisOperation extends Operation {
  public thinking$ = new Subject<Thinking>();
  private isWhite: boolean;

  constructor(
    private fen: string,
    private multiPv: number,
    postMessage: (line: string) => void,
  ) {
    super(postMessage);
    this.isWhite = getActiveColor(this.fen) === 'w';
  }

  handleWorkerMessage(line: string): boolean {
    const thinking = parseThinkingLine(line);
    if (thinking) {
      if (!this.isWhite) {
        thinking.score *= -1;
      }
      // console.log(`thinking!  ${JSON.stringify(thinking)}`);
      this.thinking$.next(thinking);
      return false;
    }

    if (line.includes('bestmove')) {
      this.thinking$.complete();
      this.resolve();
      return true;
    }

    return false;
  }
  type: OperationType = 'inf_calc';
  start(): void {
    console.debug(`Posting inf move ${this.fen}`);
    this.postMessage(`setoption name MultiPV value ${this.multiPv}`);
    this.postMessage(`position fen ${this.fen}`);
    this.postMessage(`go infinite`);
  }
  tryCancel(): void {
    this.postMessage('stop');
  }
}

//Note score is in color to move
export interface BestMoveReturn extends EvalEntry {
  uci: string;
}

interface Thinking extends EvalEntry {
  multipv: number;

  uciMove: string;

  seldepth: number;
}

export interface PublicThinking extends Thinking {
  fen: string;
}

export class StockfishEngineWrapper {
  worker: Worker;

  started = Date.now();

  public thinking$ = new Subject<PublicThinking>();

  private currentOperation: Operation | null = null;

  constructor(private logger: LoggerStore) {
    const url = getStockfishUrl();
    this.logger.log(`Building worker with ${url}`);

    this.worker = new Worker(url);
    this.logger.log(`Building worker done`);

    // bind once
    this.worker.onmessage = this.onWorkerMessage.bind(this);

    this.currentOperation = new InitOperation(this.worker.postMessage.bind(this.worker));
    this.currentOperation.start();
    //
  }

  /* ============================
   * Worker message handler
   * ============================ */
  private onWorkerMessage(e: MessageEvent | string) {
    const line: string = typeof e === 'string' ? e : e.data;

    // handle multi-line output
    if (line.indexOf('\n') > -1) {
      line.split('\n').forEach((l) => this.onWorkerMessage(l));
      return;
    }

    if (!line || line.length == 0) {
      return;
    }

    // if (debugging) {
    //   if (!line.includes('info depth')) {
    // console.log('debug (onmessage):', line);
    //   }
    // }

    if (this.currentOperation != null) {
      const operationCompleted = this.currentOperation.handleWorkerMessage(line);
      if (operationCompleted) {
        this.currentOperation = null;
      }
    } else {
      console.log(`no op but got\n${line}`);
    }
  }

  /* ============================
   * Public API
   * ============================ */

  async calculateBestMove(fen: string, calcTimeSec: number): Promise<BestMoveReturn> {
    console.debug(`Build best move ${fen} ${calcTimeSec}`);
    const bestMoveOp = new BestMoveOperation(
      fen,
      calcTimeSec,
      this.worker.postMessage.bind(this.worker),
    );

    await this.stopOngoingOperation();

    if (Operation.__sequence != bestMoveOp.sequence) {
      throw new Error(`Not last sequence, cancelling this one`);
    }

    this.currentOperation = bestMoveOp;

    bestMoveOp.start();

    console.log('await best move op');
    await bestMoveOp.done;

    if (this.currentOperation !== null) {
      throw new Error('current op should be null after done');
    }

    if (!bestMoveOp.uci || bestMoveOp.lastEval === null) {
      throw new Error(`best op failed ${bestMoveOp.uci} eval ${bestMoveOp.lastEval}`);
    }
    console.debug(`best op done ${bestMoveOp.uci} eval ${bestMoveOp.lastEval}`);
    return {
      uci: bestMoveOp.uci,
      score: bestMoveOp.lastEval.score,
      depth: bestMoveOp.lastEval.depth,
    };
  }

  async infiniteCalc(fen: string, multiPv: number = 3) {
    const infAnalysisOp = new InfiniteAnalysisOperation(
      fen,
      multiPv,
      this.worker.postMessage.bind(this.worker),
    );

    await this.stopOngoingOperation();

    //To handle multiple awaiters
    if (Operation.__sequence != infAnalysisOp.sequence) {
      throw new Error(`Not last sequence, cancelling this one`);
    }
    this.currentOperation = infAnalysisOp;
    infAnalysisOp.start();

    infAnalysisOp.thinking$.subscribe((thinking) => {
      this.thinking$.next({
        ...thinking,
        fen: fen,
      });
    });

    await infAnalysisOp.done;

    console.log(`infinite calc done fen ${fen}\n${infAnalysisOp.sequence} multiPv: ${multiPv}`);
  }

  async stopOngoingOperation() {
    if (this.currentOperation != null) {
      this.logger.debug('try cancel current op');
      this.currentOperation.tryCancel();
      await this.currentOperation.done;
      this.logger.debug('current op done');
    }

    if (this.currentOperation !== null) {
      throw new Error('current op should be null!!');
    }
  }

  quit() {
    this.worker.terminate();
  }
}

function parseThinkingLine(line: string): Thinking | null {
  const parts = line.trim().split(' ');

  let multipv = -1;
  let score = -1;
  let uciMove = '';
  let depth = 0;
  let seldepth = 0;

  for (let i = 0; i < parts.length; ++i) {
    const key = parts[i];

    if (key === 'multipv') {
      multipv = parseInt(parts[i + 1]!);
    } else if (key === 'score') {
      if (parts[i + 1] === 'cp') {
        score = parseInt(parts[i + 2]!);
        score /= 100;
      } else if (parts[i + 1] == 'mate') {
        const mateIn = parseInt(parts[i + 2]!);
        if (mateIn > 0) {
          score = MATE_SCORE * 100 - mateIn;
        } else {
          score = -MATE_SCORE * 100 - mateIn;
        }
      }
    } else if (key === 'pv') {
      uciMove = parts[i + 1]!;
    } else if (key === 'depth') {
      depth = parseInt(parts[i + 1]!);
    } else if (key === 'seldepth') {
      seldepth = parseInt(parts[i + 1]!);
    }
  }

  if (uciMove && multipv >= 1) {
    return {
      uciMove,
      score,
      multipv,
      depth,
      seldepth,
    };
  }

  return null;
}

function getStockfishUrl(): URL {
  const subPath = '/stockfish/stockfish-17.1-single-a496a04.js';

  const apiUrlOverride = import.meta.env.VITE_API_URL;

  if (apiUrlOverride) {
    return new URL(apiUrlOverride + subPath);
  }

  return new URL(
    subPath,
    /* @vite-ignore */
    window.location.origin,
  );
}
