export type PieceType = 'p' | 'r' | 'n' | 'b' | 'q' | 'k';
export type Color = 'w' | 'b';

export const TAGS = [
  'opening',
  'endgame',
  'advanced_tactics',
  'tactics',
  'bad_problem',
  'interesting',
  'defense',
  'attack',
] as const;

export type Tag = (typeof TAGS)[number];

export const STATUS = ['try_again', 'solved'] as const;

export type Status = (typeof STATUS)[number];

export interface Piece {
  type: PieceType;
  color: Color;
}

export interface LegalMove {
  from_square_index: number;
  to_square_index: number;
  uci: string;
}

export interface Move {
  from: number;
  to: number;
}
export interface HistoryEntry {
  fen: string;
  eval: number;
  lastMove: Move | null;
}

export type BoardState = (Piece | null)[];

export interface NewChessProblem {
  fen: string;
  //in point of view of player (to play of fen)
  eval: number;
  //Seconds
  last_attempt: number | null;
  status: Status | null;
  tags: Tag[];
  blunder_move_san: string;
  //in point of view of player
  blunder_move_eval: number;
  pgn_filename: string;
  game_index: number;
  pgn_tags: Record<string, string>;
  initial_move_uci: string;
}

// Generic type that adds an `id` field to any type T
export type WithId<T> = T & { id: number };

export type ChessProblem = WithId<NewChessProblem>;

export interface NewPgnFile {
  filename: string;
  //ms since 1970
  lastModified: number;
  //raw pgn content
  content: string;

  server_md5: string;

  //One of the contained games changed so content is out of date
  dirty: boolean;
}

export type PgnFile = WithId<NewPgnFile>;

export interface DbPgnGame {
  fileId: number;
  //position in the file
  gameIndex: number;
  content: string;
  title: string;
  userTitle?: string;

  //ms since 1970
  lastModified: number;
}

export interface EvalEntry {
  score: number; //in pawn score, from white point of view
  depth: number;
}

export interface MinMaxEval {
  score: number;
  min: number;
  max: number;
}
