import { usePgnStore } from '@/stores/pgn';

export function usePgnNavigation() {
  const pgnStore = usePgnStore();
  function goForward() {
    const game = pgnStore.state.currentGame;
    if (game && game.currentNode.children.length > 0) {
      game.currentNode = game.currentNode.children[0]!;
      pgnStore.state.selectedIndex = null;
      pgnStore.state.legalMoves = [];
    }
  }

  function goBack() {
    const game = pgnStore.state.currentGame;
    if (game && game.currentNode.parent) {
      game.currentNode = game.currentNode.parent;
      pgnStore.state.selectedIndex = null;
      pgnStore.state.legalMoves = [];
    }
  }

  function gotoHalfMove(halfMoveIndex: number) {
    const game = pgnStore.state.currentGame;
    if (!game) {
      return;
    }

    const targetMove = halfMoveIndex / 2;

    while (
      game.currentNode.children &&
      game.currentNode.children.length > 0 &&
      targetMove > game.currentNode.moveNumber
    ) {
      game.currentNode = game.currentNode.children[0]!;
    }
    while (game.currentNode.parent && targetMove < game.currentNode.moveNumber) {
      game.currentNode = game.currentNode.parent!;
    }
  }

  return { goForward, goBack, gotoHalfMove };
}
