import { createRouter, createWebHistory } from 'vue-router';
import ProblemView from '@/views/ProblemView.vue';
import PgnEditorView from '@/views/PgnEditorView.vue';
import PgnEditorMobileView from '@/views/PgnEditorMoblieView.vue';

export const PGN_MOBILE_ROUTE = 'pgn-mobile';
export const PGN_ROUTE = 'pgn';

const router = createRouter({
  history: createWebHistory(),
  routes: [
    {
      path: '/',
      name: 'problem',
      component: ProblemView,
    },
    {
      path: `/${PGN_ROUTE}`,
      name: `${PGN_ROUTE}`,
      component: PgnEditorView,
    },
    {
      path: `/${PGN_MOBILE_ROUTE}`,
      name: PGN_MOBILE_ROUTE,
      component: PgnEditorMobileView,
    },
  ],
});

export default router;
