<script setup lang="ts">
  import { computed, useTemplateRef, watch } from 'vue';
  import type { BoardState, LegalMove, Move } from '@/stores/interfaces';
  import ChessPiece from './ChessPiece.vue';
  import { useSwipe, type UseSwipeDirection } from '@vueuse/core';
  import { useLoggerStore } from '@/stores/logger';

  const logger = useLoggerStore();

  export interface BoardArrow {
    from: number;
    to: number;
    color?: string;
    opacity?: number;
  }

  const props = defineProps<{
    board: BoardState;
    fen: string;
    isFlipped: boolean;
    selectedIndex: number | null;
    legalMoves: LegalMove[];
    hint?: Move | null;
    lastMove?: Move | null;
    arrows?: BoardArrow[];
  }>();

  const emit = defineEmits<{
    squareClick: [index: number];
    swipe: [direction: UseSwipeDirection];
  }>();

  function getSquareColor(index: number) {
    const row = Math.floor(index / 8);
    const col = index % 8;
    return (row + col) % 2 === 0 ? 'light' : 'dark';
  }

  const displayedIndices = computed(() => {
    const indices = Array.from({ length: 64 }, (_, i) => i);
    return props.isFlipped ? indices.reverse() : indices;
  });

  const files = ['a', 'b', 'c', 'd', 'e', 'f', 'g', 'h'];
  const ranks = ['1', '2', '3', '4', '5', '6', '7', '8'];

  function getRank(realIndex: number) {
    return ranks[7 - Math.floor(realIndex / 8)];
  }

  function getFile(realIndex: number) {
    return files[realIndex % 8];
  }

  function getCenter(realIndex: number) {
    const col = realIndex % 8;
    const row = Math.floor(realIndex / 8);

    const vCol = props.isFlipped ? 7 - col : col;
    const vRow = props.isFlipped ? 7 - row : row;

    return {
      x: (vCol + 0.5) * 12.5,
      y: (vRow + 0.5) * 12.5,
    };
  }

  const el = useTemplateRef('chessBoard-el');

  const { isSwiping, direction } = useSwipe(el);

  // Watch for changes in swipe direction
  watch(direction, (newDir, oldDir) => {
    if (!isSwiping.value) {
      return;
    } // optional: only act while swiping
    logger.info('Swipe changed:', oldDir, '→', newDir);
    emit('swipe', newDir);
  });
</script>

<template>
  <div
    ref="chessBoard-el"
    class="chessboard-container"
  >
    <!-- The Board -->
    <div class="chessboard">
      <div
        v-for="(realIndex, visualIndex) in displayedIndices"
        :key="realIndex"
        class="square"
        :class="[
          getSquareColor(realIndex),
          {
            selected: selectedIndex === realIndex,
            'hint-from': hint?.from === realIndex,
            'hint-to': hint?.to === realIndex,
            'last-move': lastMove?.from === realIndex || lastMove?.to === realIndex,
          },
        ]"
        @click="emit('squareClick', realIndex)"
      >
        <!-- Rank Labels (Numbers) - Top Right of rightmost column -->
        <span
          v-if="visualIndex % 8 === 7"
          class="label rank-label"
        >
          {{ getRank(realIndex) }}
        </span>

        <!-- File Labels (Letters) - Bottom Left of bottom row -->
        <span
          v-if="visualIndex >= 56"
          class="label file-label"
        >
          {{ getFile(realIndex) }}
        </span>

        <div
          v-if="legalMoves.some((lm) => lm.to_square_index == realIndex)"
          class="move-indicator"
        />
        <div
          v-if="hint?.to === realIndex"
          class="hint-indicator"
        />

        <ChessPiece
          v-if="board[realIndex]"
          :type="board[realIndex]!.type"
          :color="board[realIndex]!.color"
        />
      </div>
    </div>

    <!-- SVG Layer for Arrows -->
    <svg
      v-if="arrows && arrows.length > 0"
      class="arrows-layer"
      viewBox="0 0 100 100"
      preserveAspectRatio="xMidYMid meet"
    >
      <defs>
        <marker
          id="arrowhead"
          markerWidth="4"
          markerHeight="4"
          refX="2"
          refY="2"
          orient="auto"
          markerUnits="strokeWidth"
        >
          <path
            d="M0,0 L4,2 L0,4"
            fill="currentColor"
          />
        </marker>
      </defs>
      <line
        v-for="(arrow, index) in arrows"
        :key="index"
        :x1="getCenter(arrow.from).x"
        :y1="getCenter(arrow.from).y"
        :x2="getCenter(arrow.to).x"
        :y2="getCenter(arrow.to).y"
        :stroke="arrow.color || 'rgba(74, 144, 226, 0.7)'"
        stroke-width="1.8"
        :opacity="arrow.opacity || 1"
        marker-end="url(#arrowhead)"
      />
    </svg>
  </div>
</template>

