<script setup lang="ts">
  import type { MinMaxEval } from '@/stores/interfaces';
  import { MAX_CP } from '@/util/pgn-tree';
  import { computed, type ComputedRef } from 'vue';
  const props = withDefaults(
    defineProps<{
      evals: MinMaxEval[];
      currentMove: number;
    }>(),
    {},
  );

  const emit = defineEmits<{
    //Half move number
    (e: 'move-click', move: number): void;
  }>();

  const VB_HEIGHT = 200;
  const VB_WIDTH = 600;

  const paths = useEvalPath(() => props.evals);

  const cursorX = computed(() => {
    if (!props.evals) {
      return 0;
    }
    if (props.evals.length < 2) {
      return 0;
    }
    return (props.currentMove / (props.evals.length - 1)) * VB_WIDTH;
  });

  // useEvalScale.ts

  const VISIBLE_MAX_CP = 3.5;

  function clampVisibleEval(cp: number) {
    return Math.max(-VISIBLE_MAX_CP, Math.min(VISIBLE_MAX_CP, cp));
  }

  function evalToY(cp: number) {
    const clamped = clampVisibleEval(cp);
    const normalized = (clamped + MAX_CP) / (2 * MAX_CP);
    return VB_HEIGHT * (1 - normalized);
  }

  function useEvalPath(evals: () => MinMaxEval[]): ComputedRef<[string, string, string]> {
    return computed(() => {
      const data = evals();
      if (!data || data.length === 0) {
        return ['', '', ''] as [string, string, string];
      }

      const minPath = data
        .map((p, i) => {
          const x = data.length === 1 ? 0 : (i / (data.length - 1)) * VB_WIDTH;
          const y = evalToY(p.min);
          return `${i === 0 ? 'M' : 'L'} ${x} ${y}`;
        })
        .join(' ');

      const maxPath = data
        .map((p, i) => {
          const x = data.length === 1 ? 0 : (i / (data.length - 1)) * VB_WIDTH;
          const y = evalToY(p.max);
          return `${i === 0 ? 'M' : 'L'} ${x} ${y}`;
        })
        .join(' ');

      const dPath = data
        .map((p, i) => {
          const x = data.length === 1 ? 0 : (i / (data.length - 1)) * VB_WIDTH;
          const y = evalToY(p.score);
          return `${i === 0 ? 'M' : 'L'} ${x} ${y}`;
        })
        .join(' ');

      return [minPath, maxPath, dPath] as [string, string, string];
    });
  }

  function onChartClick(e: MouseEvent) {
    const svg = e.currentTarget as SVGSVGElement;
    const rect = svg.getBoundingClientRect();
    const clickX = e.clientX - rect.left; // X relative to SVG
    const moveCount = props.evals.length;
    if (moveCount < 2) {
      return;
    }

    console.log(`${e.clientX} -- ${rect.left} ${rect.right} ${clickX}`);

    //chart uses full width
    const clickPerc = clickX / (rect.right - rect.left);

    // Estimate move number
    let move = Math.round(clickPerc * moveCount);
    move = Math.max(0, Math.min(move, moveCount - 1)); // clamp
    emit('move-click', move);
  }
</script>

<template>
  <svg
    viewBox="0 0 600 200"
    preserveAspectRatio="none"
    @click="onChartClick"
  >
    <!-- Background -->
    <rect
      x="0"
      y="0"
      width="600"
      height="100"
      fill="#f7f7f7"
    />
    <rect
      x="0"
      y="100"
      width="600"
      height="100"
      fill="#e5e5e5"
    />

    <!-- Zero line -->
    <line
      x1="0"
      x2="600"
      y1="100"
      y2="100"
      stroke="#888"
      stroke-dasharray="4 4"
    />

    <!-- Eval path -->

    <path
      :d="paths[0]"
      fill="none"
      stroke="#00f"
      stroke-width="2"
    />

    <path
      :d="paths[1]"
      fill="none"
      stroke="#0f0"
      stroke-width="2"
    />

    <path
      :d="paths[2]"
      fill="none"
      stroke="#111"
      stroke-width="2"
    />

    <!-- Cursor -->
    <line
      :x1="cursorX"
      :x2="cursorX"
      y1="0"
      y2="200"
      stroke="#d33"
      stroke-width="1.5"
    />
  </svg>
</template>

