<script setup lang="ts">
  import { ref } from 'vue';
  import { usePgnIO } from '@/composables/pgnIO';
  import { usePgnStore } from '@/stores/pgn';

  const pgnStore = usePgnStore();

  const { loadPgnFile, deletePgnById, renamePgnFile } = usePgnIO();

  // Track which file is being edited
  const editingFileId = ref<number | null>(null);
  const editingFilename = ref('');

  function startEditing(fileId: number, currentFilename: string) {
    editingFileId.value = fileId;
    editingFilename.value = currentFilename;
  }

  function cancelEditing() {
    editingFileId.value = null;
    editingFilename.value = '';
  }

  async function saveEdit(fileId: number) {
    if (editingFilename.value.trim()) {
      const success = await renamePgnFile(fileId, editingFilename.value);
      if (success) {
        cancelEditing();
      }
    }
  }
</script>

<template>
  <div class="pgn-file-list-tab">
    <div class="file-list">
      <div
        v-for="file in pgnStore.state.allPgnFiles"
        :key="file.id"
        class="file-item"
        :class="{ active: file.id === pgnStore.state.currentPgnFile?.id }"
        @click="editingFileId !== file.id && loadPgnFile(file)"
      >
        <div class="item-content">
          <!-- Edit mode -->
          <input
            v-if="editingFileId === file.id"
            v-model="editingFilename"
            type="text"
            class="edit-input"
            @click.stop
            @keyup.enter="saveEdit(file.id)"
            @keyup.escape="cancelEditing"
          />
          
          <!-- Normal mode -->
          <template v-else>
            <span class="file-name">
              {{ file.filename }}
            </span>
            <span class="file-info">
              {{ new Date(file.lastModified).toLocaleDateString() }}
            </span>
          </template>
        </div>

        <!-- Edit/Save/Cancel buttons -->
        <button
          v-if="editingFileId === file.id"
          class="save-btn"
          title="Save"
          @click.stop="saveEdit(file.id)"
        >
          ✓
        </button>
        <button
          v-if="editingFileId === file.id"
          class="cancel-btn"
          title="Cancel"
          @click.stop="cancelEditing"
        >
          ✗
        </button>

        <!-- Edit button (only show when not editing) -->
        <button
          v-if="editingFileId !== file.id"
          class="edit-btn"
          title="Rename file"
          @click.stop="startEditing(file.id, file.filename)"
        >
          📝
        </button>

        <!-- Delete button -->
        <button
          v-if="editingFileId !== file.id"
          class="delete-file-btn"
          title="Delete entire PGN collection"
          @click.stop="deletePgnById(file.id)"
        >
          🗑️
        </button>
      </div>
    </div>
  </div>
</template>

