<script setup lang="ts">
  import type { Color, PieceType } from '@/stores/interfaces';
  import { computed } from 'vue';

  const props = defineProps<{
    type: PieceType;
    color: Color;
  }>();

  const pieceUrl = computed(() => {
    const typeMap: Record<PieceType, string> = {
      p: 'P',
      r: 'R',
      n: 'N',
      b: 'B',
      q: 'Q',
      k: 'K',
    };
    const pieceName = `${props.color}${typeMap[props.type]}`;
    return `/pieces/${pieceName}.svg`;
  });
</script>

<template>
  <div class="piece-container">
    <img
      :src="pieceUrl"
      :alt="`${color} ${type}`"
      class="piece-img"
    />
  </div>
</template>

<style scoped>
  .piece-container {
    width: 100%;
