import type { Color, PieceType } from '../interfaces';

const PIECE_POINTS = new Map<PieceType, number>([
  ['p', 1],
  ['n', 3],
  ['b', 3],
  ['r', 5],
  ['q', 9],
  ['k', 0],
]);

const PIECE_EMOJI = new Map<PieceType, string>([
  /*['p', '♟️'],
  ['n', '♞'],
  ['b', '♝'],
  ['r', '♜'],
  ['q', '♛'],
  ['k', '♚'],*/

  ['p', '♙'], // White pawn
  ['n', '♘'],
  ['b', '♗'],
  ['r', '♖'],
  ['q', '♕'],
  ['k', '♔'],
]);

export interface MissingPiecesResult {
  white: string[];
  black: string[];

  pointDisparity: number; // white - black
}

export function calculateMissingPieces(fen: string): MissingPiecesResult {
  if (!fen) {
    return {
      white: [],
      black: [],
      pointDisparity: 0,
    };
  }

  // Start with full counts
  const whiteCount = new Map<PieceType, number>([
    ['p', 8],
    ['n', 2],
    ['b', 2],
    ['r', 2],
    ['q', 1],
    ['k', 1],
  ]);
  const blackCount = new Map<PieceType, number>([
    ['p', 8],
    ['n', 2],
    ['b', 2],
    ['r', 2],
    ['q', 1],
    ['k', 1],
  ]);

  // Count pieces on board
  const boardPieces = fen.split(' ')[0];

  if (!boardPieces) {
    throw new Error(`Invalid fen ${fen}`);
  }

  for (const char of boardPieces) {
    if (char === '/') {
      continue;
    }
    if (/\d/.test(char)) {
      continue;
    }

    const color: Color = char === char.toUpperCase() ? 'w' : 'b';
    const type = char.toLowerCase() as PieceType;
    const countMap = color === 'w' ? whiteCount : blackCount;
    countMap.set(type, (countMap.get(type) ?? 0) - 1);
  }

  const whiteMissing: string[] = [];
  const blackMissing: string[] = [];
  let whitePoints = 0;
  let blackPoints = 0;

  // Iterate over the maps directly
  for (const [type, wCount] of whiteCount.entries()) {
    const bCount = blackCount.get(type) ?? 0;

    if (wCount > bCount) {
      const missing = wCount - bCount;
      whiteMissing.push(...Array(missing).fill(PIECE_EMOJI.get(type)!));
      whitePoints += missing * PIECE_POINTS.get(type)!;
    } else if (bCount > wCount) {
      const missing = bCount - wCount;
      blackMissing.push(...Array(missing).fill(PIECE_EMOJI.get(type)!));
      blackPoints += missing * PIECE_POINTS.get(type)!;
    }
  }

  return {
    white: whiteMissing,
    black: blackMissing,

    pointDisparity: -whitePoints + blackPoints,
  };
}
