<script setup lang="ts">
  import { ref, onMounted } from 'vue';
  import { useChessStore } from '@/stores/problem';
  import type { ChessProblem } from '@/stores/interfaces';
  import { isSafeInteger } from '@/util/pgn-tree';

  const store = useChessStore();
  const emit = defineEmits<{
    closeModal: [];
  }>();

  const history = ref<ChessProblem[]>([]);

  onMounted(async () => {
    history.value = await store.getHistory();
  });

  async function loadProblem(id: number) {
    await store.fetchNextProblem(id);
    emit('closeModal');
  }

  function formatDate(timeEpoc: number | null): string {
    if (!isSafeInteger(timeEpoc)) {
      return '-';
    }
    return new Date(timeEpoc).toLocaleString();
  }
</script>

<template>
  <div class="tab-pane">
    <div
      v-if="history.length === 0"
      class="placeholder-text"
    >
      No recent attempts found.
    </div>
    <div
      v-else
      class="history-table-container"
    >
      <table class="history-table">
        <thead>
          <tr>
            <th>ID</th>
            <th>Status</th>
            <th>Last Attempted</th>
          </tr>
        </thead>
        <tbody>
          <tr
            v-for="item in history"
            :key="item.id"
          >
            <td>
              <button
                class="id-link"
                @click="loadProblem(item.id)"
              >
                #{{ item.id }}
              </button>
            </td>
            <td>
              <span
                class="status-tag"
                :class="item.status"
              >
                {{ item.status === 'solved' ? 'Solved ✅' : 'Review 🔄' }}
              </span>
            </td>
            <td class="timestamp">
              {{ formatDate(item.last_attempt) }}
            </td>
          </tr>
        </tbody>
      </table>
    </div>
  </div>
</template>

