<script setup lang="ts">
  import { useEngineStore } from '@/stores/engineStore';

  const engineStore = useEngineStore();

  const emit = defineEmits<{
    closePopup: [void];
  }>();

  function toggle() {
    engineStore.toggleAnalysis();
    emit('closePopup');
  }
</script>

<template>
  <div class="analysis-controls">
    <button
      class="toggle-btn"
      :class="{ active: engineStore.state.isAnalyzing }"
      @click="toggle"
    >
      {{ engineStore.state.isAnalyzing ? 'Stop Analysis ⏹️' : 'Start Analysis ▶️' }}
    </button>

    <div class="multipv-control">
      <span class="label">Lines: {{ engineStore.state.multiPv }}</span>
      <div class="buttons">
        <button @click="engineStore.decrementMultiPv">-</button>
        <button @click="engineStore.incrementMultiPv">+</button>
      </div>
    </div>
  </div>
</template>

