<script setup lang="ts">
  import { onMounted, ref, watch } from 'vue';
  import GameHistoryTab from '@problems/tabs/GameTab.vue';
  import ProblemTagsTab from '@problems/tabs/ProblemTagsTab.vue';
  import EngineSettingsTab from '@problems/tabs/EngineSettingsTab.vue';
  import HistoryTab from '@problems/tabs/HistoryTab.vue';
  import { useLoggerStore } from '@/stores/logger';

  const logger = useLoggerStore();

  const emit = defineEmits<{
    close: [];
  }>();

  defineProps<{
    pgnTagsTooltip: string;
  }>();

  // Load the last active tab from localStorage, default to 'game'
  const STORAGE_KEY = 'chess-options-active-tab';
  const savedTab = localStorage.getItem(STORAGE_KEY) as
    | 'game'
    | 'problem-tags'
    | 'engine-settings'
    | 'history'
    | null;
  const activeTab = ref<'game' | 'problem-tags' | 'engine-settings' | 'history'>(
    savedTab || 'game',
  );

  // Save the active tab to localStorage whenever it changes
  watch(activeTab, (newTab) => {
    localStorage.setItem(STORAGE_KEY, newTab);
  });

  onMounted(() => {
    {
      logger.info(`Inner width ${window.innerWidth} x inner height ${window.innerHeight}`);
      logger.info(`Screen width ${window.screen.width} x screen height ${window.screen.height}`);

      logger.info(
        `Physical width ${window.screen.width * window.devicePixelRatio} x physical height ${window.screen.height * window.devicePixelRatio}`,
      );

      logger.info(
        `Visual viewport width ${window.visualViewport?.width} x visual viewport height ${window.visualViewport?.height}`,
      );
    }
  });
</script>

<template>
  <div
    class="modal-overlay"
    @click="emit('close')"
  >
    <div
      class="options-modal"
      @click.stop
    >
      <h3>Game Options</h3>

      <!-- Tab Navigation -->
      <div class="tab-nav">
        <button
          :class="{ active: activeTab === 'game' }"
          @click="activeTab = 'game'"
        >
          Game
        </button>
        <button
          :class="{ active: activeTab === 'problem-tags' }"
          @click="activeTab = 'problem-tags'"
        >
          Problem Tags
        </button>
        <button
          :class="{ active: activeTab === 'engine-settings' }"
          @click="activeTab = 'engine-settings'"
        >
          Engine Settings
        </button>
        <button
          :class="{ active: activeTab === 'history' }"
          @click="activeTab = 'history'"
        >
          History
        </button>
      </div>

      <!-- Tab Content -->
      <div class="tab-content">
        <GameHistoryTab
          v-if="activeTab === 'game'"
          :pgn-tags-tooltip="pgnTagsTooltip"
          @close-modal="emit('close')"
        />
        <ProblemTagsTab v-if="activeTab === 'problem-tags'" />
        <EngineSettingsTab
          v-if="activeTab === 'engine-settings'"
          @close-modal="emit('close')"
        />
        <HistoryTab
          v-if="activeTab === 'history'"
          @close-modal="emit('close')"
        />
      </div>

      <button
        class="close-btn"
        @click="emit('close')"
      >
        Close
      </button>
    </div>
  </div>
</template>

