<script setup lang="ts">
  import { useChessStore } from '@/stores/problem';

  const store = useChessStore();

  const emit = defineEmits<{
    toggleOptions: [];
  }>();

  function toggleAnalyze() {
    if (!store.game.isAnalyze) {
      store.startAnalyze();
    } else {
      store.stopAnalyze();
    }
  }

  function undoAll() {
    while (store.game.history.length > 0) {
      store.undoMove();
    }
  }
</script>

<template>
  <div class="items-container">
    <div class="flex-break" />
    <button
      class="mini-btn undo-move"
      :disabled="store.game.history.length === 0"
      @click="store.undoMove"
    >
      Undo ↩️
    </button>

    <button
      class="mini-btn undo-all"
      :disabled="store.game.history.length === 0"
      @click="undoAll"
    >
      Undo All ⏪
    </button>

    <button
      class="mini-btn solved-color"
      @click="store.updateProblemStatus('solved')"
    >
      Solved ✅
    </button>
    <button
      class="mini-btn try-again-color"
      @click="store.updateProblemStatus('try_again')"
    >
      Review 🔄
    </button>

    <button
      class="mini-btn"
      @click="emit('toggleOptions')"
    >
      Settings ⚙️
    </button>

    <button
      class="mini-btn"
      @click="toggleAnalyze"
    >
      Analyze {{ store.game.isAnalyze ? 'ON' : 'OFF' }}
    </button>

    <button
      class="mini-btn"
      @click="$router.push('/pgn')"
    >
      PGN Editor 📝
    </button>

    <div class="flex-break" />

    <div v-if="store.game.isAnalyze">
      {{ store.ui.bestMoveAnalysis.join(' ') }}
    </div>
  </div>
</template>

<style scoped lang="less">
  @import '@/style/shared.less';

  .mini-btn.solved-color {
    background: rgba(76, 217, 100, 0.2);
