<script setup lang="ts">
  import { ref, onMounted, onUnmounted, watch, computed } from 'vue';
  import { usePgnStore } from '@/stores/pgn';
  import { useEngineStore } from '@/stores/engineStore';
  import { useLoggerStore } from '@/stores/logger';

  import { uciToIndex } from '@/stores/util/uci';
  import ChessBoard, { type BoardArrow } from '@/components/ChessBoard.vue';
  import PgnVariationsTab from '@pgn/tabs/PgnVariationsTab.vue';
  import PgnCommentsTab from '@pgn/tabs/PgnCommentsTab.vue';
  import PgnGameListTab from '@pgn/tabs/PgnGameListTab.vue';
  import PgnFileListTab from '@pgn/tabs/PgnFileListTab.vue';
  import PgnAnalysisTab from '@pgn/tabs/PgnAnalysisTab.vue';

  import PgnHeader from '@pgn/PgnHeader.vue';
  import type { UseSwipeDirection } from '@vueuse/core';
  import { usePgnIO } from '@/composables/pgnIO';
  import { usePgnNavigation } from '@/composables/pgnNavigation';
  import { usePgnEdit } from '@/composables/pgnEdit';

  const pgnStore = usePgnStore();
  const engineStore = useEngineStore();
  const logger = useLoggerStore();

  type TabType = 'variations' | 'comments' | 'analysis' | 'game-list' | 'pgn-files';
  const savedTab = localStorage.getItem('pgnActiveTab') as TabType;
  const activeTab = ref<TabType>(
    ['variations', 'comments', 'analysis', 'game-list', 'pgn-files'].includes(savedTab)
      ? savedTab
      : 'pgn-files',
  );

  const { goForward, goBack } = usePgnNavigation();

  const { loadPgnFiles, handleCopyCurrentGame } = usePgnIO();

  const { selectSquare } = usePgnEdit();

  watch(activeTab, (newTab) => {
    localStorage.setItem('pgnActiveTab', newTab);
  });

  const boardArrows = computed<BoardArrow[]>(() => {
    return engineStore.state.analysisResults
      .filter((line) => line.uciMove && line.uciMove !== '(none)')
      .map((line) => ({
        from: uciToIndex(line.uciMove.substring(0, 2)),
        to: uciToIndex(line.uciMove.substring(2, 4)),
        opacity: Math.max(0.2, 1 - (line.multipv - 1) * 0.3),
      }));
  });

  function handleKeyDown(e: KeyboardEvent) {
    if (
      document.activeElement?.tagName === 'INPUT' ||
      document.activeElement?.tagName === 'TEXTAREA'
    ) {
      return;
    }

    if (e.key === 'ArrowRight') {
      goForward();
    } else if (e.key === 'ArrowLeft') {
      goBack();
    }
  }

  onMounted(async () => {
    await loadPgnFiles();
    window.addEventListener('keydown', handleKeyDown);
  });

  onUnmounted(() => {
    window.removeEventListener('keydown', handleKeyDown);
    engineStore.stopAnalysis();
  });

  function handleSwipe(direction: UseSwipeDirection) {
    logger.info(`Swipe ${direction}`);

    if (direction == 'up') {
      //headerVisible.value = !headerVisible.value
    }
    if (direction == 'down') {
      //boardButtonsVisible.value = !boardButtonsVisible.value;
    }
  }
</script>

<template>
  <div class="pgn-editor main-container">
    <div class="sub-main-container-never-wrap">
      <header class="header">
        <PgnHeader />
      </header>

      <div class="board-wrapper">
        <ChessBoard
          :board="pgnStore.currentBoard"
          :fen="pgnStore.currentFen"
          :is-flipped="pgnStore.state.isFlipped"
          :selected-index="pgnStore.state.selectedIndex"
          :legal-moves="pgnStore.state.legalMoves"
          :arrows="boardArrows"
          @square-click="selectSquare"
          @swipe="handleSwipe"
        />
      </div>
      <div class="board-controls items-container">
        <button @click="pgnStore.toggleFlip">Flip Board 🔄</button>
        <button @click="goBack">Back ⬅️</button>
        <button
          :disabled="!pgnStore.state.currentGame"
          @click="handleCopyCurrentGame"
        >
          Copy Game 📋
        </button>
        <div>
          {{ pgnStore.missingPieces.pointDisparity }}
          <span class="white-pieces">{{ pgnStore.missingPieces.white.join('') }}</span>
          <span class="black-pieces">{{ pgnStore.missingPieces.black.join('') }}</span>
        </div>
        <div v-show="pgnStore.state.showDelta">Eval Diff: {{ pgnStore.state.deltaInfo }}</div>
      </div>
    </div>

    <div class="flex-break-pc" />

    <div class="tabs-container info-pane">
      <div class="tabs-buttons">
        <button
          :class="{ active: activeTab === 'variations' }"
          @click="activeTab = 'variations'"
        >
          Variations
        </button>
        <button
          :class="{ active: activeTab === 'comments' }"
          @click="activeTab = 'comments'"
        >
          Comments
        </button>
        <button
          :class="{ active: activeTab === 'analysis' }"
          @click="activeTab = 'analysis'"
        >
          Analysis
        </button>
        <button
          :class="{ active: activeTab === 'game-list' }"
          @click="activeTab = 'game-list'"
        >
          Game List
        </button>
        <button
          :class="{ active: activeTab === 'pgn-files' }"
          @click="activeTab = 'pgn-files'"
        >
          PGN Files
        </button>
      </div>

      <div class="tabs-content">
        <PgnVariationsTab v-if="activeTab === 'variations'" />
        <PgnCommentsTab v-if="activeTab === 'comments'" />
        <PgnAnalysisTab v-if="activeTab === 'analysis'" />
        <PgnGameListTab v-if="activeTab === 'game-list'" />
        <PgnFileListTab v-if="activeTab === 'pgn-files'" />
      </div>
    </div>
  </div>
</template>

