<script setup lang="ts">
  import { ref } from 'vue';
  import { usePgnIO } from '@/composables/pgnIO';

  const emit = defineEmits<{
    closePopup: [void];
  }>();

  const { createEmptyPgnFile } = usePgnIO();

  const showNewFileDialog = ref(false);
  const newFilename = ref('');

  async function handleCreateFile() {
    if (!newFilename.value.trim()) {
      return;
    }

    const success = await createEmptyPgnFile(newFilename.value);
    if (success) {
      newFilename.value = '';
      showNewFileDialog.value = false;
      emit('closePopup');
    }
  }

  function openNewFileDialog() {
    newFilename.value = '';
    showNewFileDialog.value = true;
  }

  function cancelNewFile() {
    newFilename.value = '';
    showNewFileDialog.value = false;
  }
</script>

<template>
  <div class="actions">
    <!-- Main menu -->
    <div
      v-if="!showNewFileDialog"
      class="action-row items-container"
    >
      <button
        class="new-file-btn"
        @click="openNewFileDialog"
      >
        New File 📄
      </button>
    </div>

    <!-- New file form -->
    <div
      v-if="showNewFileDialog"
      class="new-file-form"
    >
      <label for="filename-input">New PGN Filename:</label>
      <input
        id="filename-input"
        v-model="newFilename"
        type="text"
        placeholder="e.g., my_games.pgn"
        @keyup.enter="handleCreateFile"
        @keyup.escape="cancelNewFile"
      />
      <div class="form-buttons items-container">
        <button
          class="cancel-btn"
          @click="cancelNewFile"
        >
          Cancel
        </button>
        <button
          class="create-btn"
          :disabled="!newFilename.trim()"
          @click="handleCreateFile"
        >
          Create
        </button>
      </div>
    </div>
  </div>
</template>

