<script setup lang="ts">
  import { useChessStore } from '@/stores/problem';
  import { TAGS, type Tag } from '@/stores/interfaces';

  const store = useChessStore();

  function formatTag(tag: string) {
    return tag
      .split('_')
      .map((word) => word.charAt(0).toUpperCase() + word.slice(1))
      .join(' ');
  }

  function toggleTag(tag: Tag) {
    const currentTags = [...store.problem.tags];
    let newTags: Tag[];
    if (currentTags.includes(tag)) {
      newTags = currentTags.filter((t) => t !== tag);
    } else {
      newTags = [...currentTags, tag];
    }
    store.updateProblemTags(newTags);
  }
</script>

<template>
  <div class="tab-pane">
    <h4>Tags</h4>

    <div
      v-if="store.problem.tags"
      class="current-tags"
    >
      Current: {{ store.problem.tags.join(', ') }}
    </div>

    <div class="tag-group">
      <button
        v-for="tag in TAGS"
        :key="tag"
        :class="{ active: store.problem.tags.includes(tag) }"
        @click="toggleTag(tag)"
      >
        {{ formatTag(tag) }}
      </button>
    </div>
  </div>
</template>

