<script setup lang="ts">
  import {
    computed,
    ref,
    watch,
    onMounted,
    type ComponentPublicInstance,
    watchEffect,
    nextTick,
  } from 'vue'; // turbo-boost
  import { usePgnStore } from '@/stores/pgn';

  import { flattenPgnTree, type PgnNode, nagToSymbol, isSafeInteger } from '@/util/pgn-tree';
  import { NEW_COMMENT_TEXT } from '@/composables/pgnEdit';
  import { usePgnIO } from '@/composables/pgnIO';

  const props = withDefaults(
    defineProps<{
      node: PgnNode | undefined;
      currentNode: PgnNode | undefined;
      depth?: number;
    }>(),
    {
      depth: 0,
    },
  );

  const emit = defineEmits<{
    navigate: [node: PgnNode];
  }>();

  const pgnStore = usePgnStore();

  const { saveCurrentGame } = usePgnIO();

  const editCommentTextarea = ref<HTMLTextAreaElement | null>(null); //('editCommentTextarea');
  //const editCommentText = ref('');

  function startEditing(node: PgnNode | undefined) {
    if (!node) {
      return;
    }
    pgnStore.state.editingCommentNodeId = node.uid;
    // Clear "New Comment" placeholder text when starting to edit
    //editCommentText.value = text === 'New Comment' ? '' : text;
    // Make sure we are on this node so updates feel natural (optional, but good for context)
    emit('navigate', node);
  }

  function cancelEditing() {
    pgnStore.state.editingCommentNodeId = null;
  }

  watchEffect(async () => {
    if (editCommentTextarea.value) {
      await nextTick();
      console.debug(`Current text ${editCommentTextarea.value.value}`);
      if (editCommentTextarea.value.value == NEW_COMMENT_TEXT) {
        editCommentTextarea.value.value = '';
      }
      editCommentTextarea.value.focus();
    }
  });

  async function saveComment() {
    pgnStore.state.editingCommentNodeId = null;

    await saveCurrentGame();
  }

  function getNagSymbol(node: PgnNode) {
    if (!isSafeInteger(node.nag)) {
      return '';
    }
    // Just find the first move eval nag for now
    return nagToSymbol(node.nag);
  }

  const flatItems = computed(() => {
    if (!props.node) {
      return [];
    }
    return flattenPgnTree(props.node, props.depth);
  });

  const moveRefs = new Map<string, HTMLElement>();

  function setRef(el: Element | ComponentPublicInstance | null, node: PgnNode) {
    if (el) {
      moveRefs.set(node.uid, el as HTMLElement);
    } else {
      moveRefs.delete(node.uid);
    }
  }

  function scrollToNode(node: PgnNode | undefined) {
    if (!node) {
      return;
    }
    const el = moveRefs.get(node.uid);
    if (el) {
      el.scrollIntoView({
        behavior: 'smooth',
        block: 'nearest',
        inline: 'nearest',
      });
    }
  }

  watch(
    () => props.currentNode,
    (newNode) => {
      // Use requestAnimationFrame or nextTick (flush: 'post' handles nextTick mostly)
      // to ensure DOM is ready if it's a new node.
      scrollToNode(newNode);
    },
    { flush: 'post' },
  );

  onMounted(() => {
    scrollToNode(props.currentNode);
  });
</script>

<template>
  <div class="pgn-flat-tree">
    <div
      v-for="item in flatItems"
      :key="item.id"
      class="item-row"
      :class="[`depth-${item.depth}`, item.type]"
    >
      <!-- Move Pair (W+B) -->
      <template v-if="item.type === 'move-pair'">
        <span class="move-num">{{ item.white!.moveNumber }}.</span>
        <span
          :ref="(el) => setRef(el, item.white!)"
          class="move"
          :class="{ active: currentNode === item.white }"
          @click="emit('navigate', item.white!)"
        >
          {{ item.white!.san }}{{ getNagSymbol(item.white!) }}
        </span>
        <span
          :ref="(el) => setRef(el, item.black!)"
          class="move"
          :class="{ active: currentNode === item.black }"
          @click="emit('navigate', item.black!)"
        >
          {{ item.black!.san }}{{ getNagSymbol(item.black!) }}
        </span>
      </template>

      <!-- Single Move -->
      <template v-else-if="item.type === 'single-move'">
        <span class="move-num">
          {{ item.node!.moveNumber }}
          <template v-if="item.showEllipsis">...</template>
          <template v-else>.</template>
        </span>
        <span
          :ref="(el) => setRef(el, item.node!)"
          class="move"
          :class="{ active: currentNode === item.node }"
          @click="emit('navigate', item.node!)"
        >
          {{ item.node!.san }}{{ getNagSymbol(item.node!) }}
        </span>
      </template>

      <!-- Comment -->
      <template v-else-if="item.type === 'comment'">
        <div
          v-if="pgnStore.state.editingCommentNodeId === item.node?.uid"
          class="comment-edit"
        >
          <textarea
            :ref="
              (el) => {
                editCommentTextarea = el as HTMLTextAreaElement;
              }
            "
            v-model="item.node.comment"
            rows="2"
            @blur="saveComment()"
            @keydown.enter.exact.prevent="saveComment()"
            @keydown.esc="cancelEditing"
          />
        </div>
        <div
          v-else
          class="comment-text"
          @click="startEditing(item.node)"
        >
          { {{ item.text }} }
        </div>
      </template>
    </div>
  </div>
</template>

