  /* Depth Styles - Generated Programmatically */
  .generate-depth-styles(@max-depth: 4) {
    .depth-loop(@i) when (@i <= @max-depth) {
      @margin: (@i * 1rem);
      @border-lightness: (58 + (@i * 16));
      @bg-opacity: (0.01 + (@i * 0.01));
      @move-num-lightness: (170 - (@i * 17));

      .depth-@{i} {
        margin-left: @margin;
        border-left: 2px solid hsl(0, 0%, unit(@border-lightness, '%'));
        padding-left: var(--spacing-md);
        background: rgba(255, 255, 255, @bg-opacity);
      }

      .depth-@{i} .move-num {
        color: hsl(0, 0%, unit(@move-num-lightness, '%'));
      }

      .depth-loop(@i + 1);
    }

    // Start the loop at 1
    .depth-loop(1);
  }

  .generate-depth-styles();
