<script setup lang="ts">
  import { ref, watch } from 'vue';
  import { usePgnStore } from '@/stores/pgn';
  import { usePgnEdit } from '@/composables/pgnEdit';

  const pgnStore = usePgnStore();
  const commentText = ref('');

  const { deleteCurrentComment, setComment, setUserTitle } = usePgnEdit();

  watch(
    () => pgnStore.currentNode?.comment,
    (newComment) => {
      commentText.value = newComment || '';
    },
    { immediate: true },
  );

  function updateComment() {
    setComment(commentText.value);
  }
</script>

<template>
  <div class="pgn-comments-tab">
    <div
      v-if="pgnStore.state.currentGame"
      class="user-title-section"
    >
      <label>Game Title / Comment:</label>
      <input
        type="text"
        placeholder="Add your comment about this game..."
        :value="pgnStore.state.currentGame.headers.get('UserTitle') || ''"
        @input="setUserTitle(($event.target as HTMLInputElement).value)"
      />
    </div>

    <label>Move Comment:</label>
    <textarea
      v-model="commentText"
      placeholder="Add a comment for this move..."
      @input="updateComment"
    />
    <button
      v-if="pgnStore.state.currentGame"
      class="delete-btn"
      @click="deleteCurrentComment"
    >
      Delete Comment 🗑️
    </button>
  </div>
</template>

