import Dexie from 'dexie';
import type { ChessProblem, NewPgnFile, PgnFile, DbPgnGame, NewChessProblem } from './interfaces';
import { splitPgnStream } from './util/pgn_splitter';

interface HistoryEntry {
  timestamp: number;
  problemId: number;
}

class ChessDB extends Dexie {
  problems: Dexie.Table<ChessProblem, number>;
  history: Dexie.Table<HistoryEntry, number>;
  pgns: Dexie.Table<PgnFile, number>;
  pgn_games: Dexie.Table<DbPgnGame, [number, number]>;

  constructor() {
    super('chess-db');

    this.version(7).stores({
      problems: 'id++, status, last_attempt',
      history: '++id',
      //unique index on filename
      pgns: '++id, &filename',
      //compound primary key
      pgn_games: '[fileId+gameIndex]',
      evals: 'fen',
    });

    this.problems = this.table('problems');
    this.history = this.table('history');
    this.pgns = this.table('pgns');
    this.pgn_games = this.table('pgn_games');
  }

  // -------------------------
  // Problem CRUD
  // -------------------------
  async storeProblems(problems: NewChessProblem[]): Promise<void> {
    await this.problems.bulkPut(problems as Array<ChessProblem>);
  }

  async updateProblem(problem: ChessProblem): Promise<void> {
    await this.problems.put(problem);
  }

  async getProblemById(id: number): Promise<ChessProblem | undefined> {
    return this.problems.get(id);
  }

  async getAllProblems(): Promise<ChessProblem[]> {
    return this.problems.toArray();
  }

  async getProblemCount(): Promise<number> {
    return this.problems.count();
  }

  async getFilteredProblems(): Promise<ChessProblem[]> {
    const allProblems = await this.getAllProblems();

    return allProblems
      .filter((p) => p.status !== 'solved')
      .filter((p) => !p.tags.includes('bad_problem'));
  }

  async getFilteredProblemCount(): Promise<number> {
    return (await this.getFilteredProblems()).length;
  }

  async getNextProblem(): Promise<ChessProblem | null> {
    const filteredProblems = await this.getFilteredProblems();
    if (filteredProblems.length === 0) {
      return null;
    }

    const neverAttempted = filteredProblems.filter((p) => !p.last_attempt);
    if (neverAttempted.length > 0) {
      return neverAttempted[Math.floor(Math.random() * neverAttempted.length)]!;
    }

    // Sort by last_attempt ascending
    filteredProblems.sort((a, b) => {
      if (!a.last_attempt) {
        return -1;
      }
      if (!b.last_attempt) {
        return 1;
      }
      return new Date(a.last_attempt).getTime() - new Date(b.last_attempt).getTime();
    });

    return filteredProblems[0]!;
  }

  // -------------------------
  // History
  // -------------------------
  async addToHistory(problemId: number): Promise<void> {
    await this.history.put({ problemId, timestamp: Date.now() });

    // Keep only last 10 entries
    const allHistory = await this.history.toArray();
    if (allHistory.length > 10) {
      const toDelete = allHistory.sort((a, b) => b.timestamp - a.timestamp).slice(10);
      await Promise.all(toDelete.map((h) => this.history.delete(h.timestamp)));
    }
  }

  async getHistory(): Promise<ChessProblem[]> {
    const entries = (await this.history.toArray()).sort((a, b) => b.timestamp - a.timestamp);

    const problems: ChessProblem[] = [];
    for (const entry of entries) {
      const problem = await this.getProblemById(entry.problemId);
      if (problem) {
        problems.push(problem);
      }
    }
    return problems;
  }

  // -------------------------
  // PGN
  // -------------------------
  async storePgn(pgn: NewPgnFile): Promise<number> {
    if (Number.isSafeInteger((pgn as PgnFile).id)) {
      throw new Error(`Should not pass id to pgn`);
    }
    const pgnFileId = await this.pgns.add(pgn as PgnFile);

    //const pgnFileId = (pgn as PgnFile).id;

    //also split and store the games
    let gameIndex = 0;
    const gamesToStore: Array<DbPgnGame> = [];
    for (const pgnGameContent of splitPgnStream(pgn.content)) {
      const userTitle = extractUserTitle(pgnGameContent);
      const title = extractTitle(pgnGameContent);
      const game: DbPgnGame = {
        fileId: pgnFileId,
        gameIndex,
        content: pgnGameContent,
        title: title ?? `Game #${gameIndex}`,
        userTitle: userTitle,
        lastModified: Date.now(),
      };
      ++gameIndex;
      gamesToStore.push(game);
    }

    await this.pgn_games.bulkAdd(gamesToStore);

    return pgnFileId;
  }

  async updatePgn(pgn: PgnFile): Promise<void> {
    const updatedCount = await this.pgns.update(pgn.id, pgn);

    if (updatedCount != 1) {
      throw new Error(`Updated count was ${updatedCount} for ${pgn.id}`);
    }
  }

  async updatePgnGame(pgnGame: DbPgnGame): Promise<void> {
    const updatedCount = await this.pgn_games.update([pgnGame.fileId, pgnGame.gameIndex], pgnGame);

    if (updatedCount != 1) {
      throw new Error(
        `Updated count was ${updatedCount} for ${pgnGame.fileId} ${pgnGame.gameIndex}`,
      );
    }

    await this.setDbPgnDirty(pgnGame.fileId);
  }

  private async setDbPgnDirty(fileId: number) {
    //Set dirty on pgn file
    const dbPgnFile = await this.getPgnById(fileId);

    if (!dbPgnFile.dirty) {
      dbPgnFile.dirty = true;
      dbPgnFile.server_md5 = 'changed';
      await this.updatePgn(dbPgnFile);
    }
  }

  async getAllPgns(): Promise<PgnFile[]> {
    return this.pgns.toArray();
  }

  async getPgnById(id: number): Promise<PgnFile> {
    const pgn = await this.pgns.get(id);
    if (!pgn) {
      throw new Error(`pgn not found ${id}`);
    }
    return pgn;
  }

  async getPgnByFilename(filename: string): Promise<PgnFile | undefined> {
    return this.pgns.where('filename').equals(filename).first();
  }

  async deletePgn(id: number): Promise<void> {
    await this.pgns.delete(id);
  }

  async addGameToPgn(
    partialGame: Omit<DbPgnGame, 'lastModified' | 'gameIndex' | 'userTitle' | 'title'>,
  ): Promise<number> {
    //Invariant maintained that gameIndex is order in the file
    const existingGamesCount = await this.pgn_games
      .where('fileId')
      .equals(partialGame.fileId)
      .count();
    const nextIndex = existingGamesCount;

    const userTitle = extractUserTitle(partialGame.content);
    const title = extractTitle(partialGame.content);

    const game: DbPgnGame = {
      ...partialGame,
      gameIndex: nextIndex,
      lastModified: Date.now(),
      userTitle,
      title: title ?? `Game #${nextIndex}`,
    };

    await this.pgn_games.add(game);

    await this.setDbPgnDirty(game.fileId);

    return nextIndex;
  }

  async deletePgnGame(fileId: number, gameIndex: number): Promise<void> {
    await this.transaction('rw', this.pgn_games, this.pgns, async () => {
      await this.pgn_games.delete([fileId, gameIndex]);

      // Re-index remaining games to close gaps
      const remainingGames = await this.pgn_games
        .where('fileId')
        .equals(fileId)
        .sortBy('gameIndex');

      for (let i = 0; i < remainingGames.length; i++) {
        const game = remainingGames[i]!;
        if (game.gameIndex !== i) {
          // We need to delete the old key and add with new key because gameIndex is part of PK
          await this.pgn_games.delete([game.fileId, game.gameIndex]);
          game.gameIndex = i;
          await this.pgn_games.add(game);
        }
      }

      await this.setDbPgnDirty(fileId);
    });
  }

  async getGames(pgnFileId: number): Promise<Array<DbPgnGame>> {
    return await this.pgn_games.where('fileId').equals(pgnFileId).sortBy('gameIndex');
  }

  // -------------------------
  // Export entire DB
  // -------------------------
  async exportDB(): Promise<Record<string, unknown[]>> {
    const [problems, history, pgns] = await Promise.all([
      this.problems.toArray(),
      this.history.toArray(),
      this.pgns.toArray(),
    ]);

    return {
      problems,
      history,
      pgns,
    };
  }
}

function extractUserTitle(pgnContent: string): string | undefined {
  const match = pgnContent.match(/\[UserTitle "([^"]+)"\]/);
  return match && match[1] ? match[1] : undefined;
}
function extractTitle(pgnContent: string): string | null {
  const whiteMatch = pgnContent.match(/\[White "([^"]+)"\]/);
  const blackMatch = pgnContent.match(/\[Black "([^"]+)"\]/);
  const resultMatch = pgnContent.match(/\[Result "([^"]+)"\]/);
  if (!whiteMatch || !blackMatch || !resultMatch) {
    return null;
  }
  return `${whiteMatch[1]} vs ${blackMatch[1]} ${resultMatch[1]}`;
}

// -------------------------
// Singleton instance
// -------------------------
export const chessDb = new ChessDB();
