import { defineStore } from 'pinia';
import { reactive, watch, computed } from 'vue';
import { StockfishEngineWrapper, type PublicThinking } from './util/load_engine';
import { useLoggerStore } from './logger';
import { getActiveColor } from './util/fen';

import { getSan, type PgnNode } from '@/util/pgn-tree';
import { usePgnStore } from './pgn';

export interface AnalysisLine extends PublicThinking {
  san?: string;
  pv?: string[]; // Full principal variation
}

/*
Used in the pgn editor view currently, as in for an entire game
*/
export const useEngineStore = defineStore('engine', () => {
  const logger = useLoggerStore();

  const pgnStore = usePgnStore();
  const stockfish = new StockfishEngineWrapper(logger);

  const state = reactive({
    isAnalyzing: false,
    multiPv: Number(localStorage.getItem('engineMultiPv')) || 3,
    analysisResults: [] as AnalysisLine[],
  });

  // Persist MultiPV setting
  watch(
    () => state.multiPv,
    (val) => {
      localStorage.setItem('engineMultiPv', val.toString());
      if (state.isAnalyzing) {
        // Restart analysis with new MultiPV
        startAnalysis();
      }
    },
  );

  watch(
    () => pgnStore.currentNode,
    async (node) => {
      pgnStore.state.deltaInfo = '';

      if (!pgnStore.state.showDelta) {
        //its disabled
        return;
      }

      if (!node) {
        return;
      }
      if (!node.parent) {
        return;
      }
      if (!pgnStore.state.currentGame) {
        return;
      }
      console.log(`node changed ${pgnStore.state.showDelta}`);

      const prevFen = node.parent?.fen;
      const curFen = node.fen;

      if (!prevFen) {
        return;
      }
      if (!curFen) {
        return;
      }

      pgnStore.state.deltaInfo = `Starting calc -- depth: ${node.variationDepth}`;
      const results = await calculateDelta(node.parent, node);

      //if results for top player, then -1
      console.log(
        `Active prev fen ${getActiveColor(prevFen)} cur fen ${getActiveColor(curFen)} is flipped ${pgnStore.state.isFlipped}`,
      );

      pgnStore.state.deltaInfo = `Delta ${results[0].toFixed(2)} CurEval ${results[1].toFixed(2)}`;
    },
  );

  stockfish.thinking$.subscribe((thinking) => {
    // Check if thinking belongs to current FEN (simple check, could improve with sequence IDs)
    const lineIndex = thinking.multipv - 1;

    const currentNode = pgnStore.state.currentGame?.currentNode;

    if (!currentNode) {
      logger.warn('No current node');
      return;
    }

    if (thinking.fen != currentNode.fen) {
      logger.warn(`Thinking fen ${thinking.fen} does not match ${currentNode.fen}, ignoring`);
      return;
    }

    const san = getSan(thinking.uciMove, currentNode.fen);

    if (thinking.multipv <= 1 && (!currentNode.eval || currentNode.eval.depth < thinking.depth)) {
      console.info(`Fen ${thinking.fen} -> ${thinking.score} thinking`);
      currentNode.eval = { depth: thinking.depth, score: thinking.score };
      console.debug('Setting dirty true');
      pgnStore.state.currentGame!.isDirty = true;
      //fenEvalCache.set(thinking.fen, thinking.score);
    }

    thinking.score *= calcFlipScore();

    // Convert thinking to our simpler AnalysisLine format
    // Note: SAN conversion might be better handled by the component or a helper
    state.analysisResults[lineIndex] = {
      ...thinking,
      san,
    };
  });

  function startAnalysis() {
    const curNode = pgnStore.state.currentGame?.currentNode;
    if (!curNode) {
      logger.warn('No current node');
      return;
    }
    state.isAnalyzing = true;
    state.analysisResults = [];

    stockfish.infiniteCalc(curNode.fen, state.multiPv);
  }

  async function stopAnalysis() {
    if (state.isAnalyzing) {
      await stockfish.stopOngoingOperation();
    }
    state.isAnalyzing = false;
    state.analysisResults = [];

    //Flush
  }

  function toggleAnalysis() {
    if (state.isAnalyzing) {
      stopAnalysis();
    } else {
      startAnalysis();
    }
  }

  async function calculateDelta(prevNode: PgnNode, curNode: PgnNode): Promise<[number, number]> {
    console.info(`Calculating delta`);
    const timeLimitSeconds = 0.5;

    if (!curNode.eval) {
      const bm = await stockfish.calculateBestMove(curNode.fen, timeLimitSeconds);
      curNode.eval = { depth: bm.depth, score: bm.score };
      console.debug('Setting dirty true');
      pgnStore.state.currentGame!.isDirty = true;
    }

    //not root
    if (prevNode.moveNumber <= 0) {
      return [calcFlipScore() * (curNode.eval.score - 0), curNode.eval.score * calcFlipScore()];
    }

    if (!prevNode.eval) {
      const bm = await stockfish.calculateBestMove(prevNode.fen, timeLimitSeconds);
      prevNode.eval = { depth: bm.depth, score: bm.score };
      console.debug('Setting dirty true');
      pgnStore.state.currentGame!.isDirty = true;
    }

    // console.log(`Delta ${prevScore} vs ${curScore} -- flipped -- ${calcFlipScore(curFen)}`);
    return [
      calcFlipScore() * (curNode.eval.score - prevNode.eval.score),
      curNode.eval.score * calcFlipScore(),
    ];
  }

  function incrementMultiPv() {
    if (state.multiPv >= 5) {
      return;
    }
    if (state.isAnalyzing) {
      stopAnalysis();
    }
    state.multiPv++;

    startAnalysis();
  }

  async function decrementMultiPv() {
    if (state.multiPv > 1) {
      if (state.isAnalyzing) {
        await stopAnalysis();
      }
      state.multiPv--;
      // Immediately trim results
      if (state.analysisResults.length > state.multiPv) {
        state.analysisResults.splice(state.multiPv);
      }

      startAnalysis();
    }
  }

  const bestMove = computed(() => state.analysisResults[0] || null);

  function calcFlipScore(): number {
    return pgnStore.state.isFlipped ? -1 : 1;
  }

  return {
    state,
    bestMove,
    startAnalysis,
    stopAnalysis,
    toggleAnalysis,
    incrementMultiPv,
    decrementMultiPv,
    calculateDelta,
  };
});
