import { chessDb } from '@/stores/client_database';
import { useEngineStore } from '@/stores/engineStore';
import type { ChessProblem, NewChessProblem } from '@/stores/interfaces';
import { useLoggerStore } from '@/stores/logger';
import { usePgnStore } from '@/stores/pgn';
import { indexToUci, uciToIndex } from '@/stores/util/uci';
import {
  addMove,
  isMainline,
  nagToSymbol,
  promoteNode,
  setNag,
  trimToNull,
  type PgnNode,
} from '@/util/pgn-tree';
import { Chess } from 'chess.ts';
import { computed } from 'vue';
import { useSnackbar } from 'vue3-snackbar';

export const NEW_COMMENT_TEXT = 'New Comment';

export function usePgnEdit() {
  const pgnStore = usePgnStore();
  const logger = useLoggerStore();
  const snackbar = useSnackbar();
  const engineStore = useEngineStore();

  function formatNag(nag: number): string {
    return nagToSymbol(nag);
  }

  function toggleDelta() {
    pgnStore.state.showDelta = !pgnStore.state.showDelta;
  }

  const canPromote = computed(() => {
    const game = pgnStore.state.currentGame;
    if (!game) {
      return false;
    }

    const node = game.currentNode;

    if (!node) {
      return false;
    }

    //sub sub, because promote means replace 1st child, not
    //yet to have child[n] become child[1]
    return node.variationDepth > 1;
  });

  function toggleComment() {
    const node = pgnStore.currentNode;
    if (!node) {
      return;
    }
    const addingComment = !node.comment;

    if (!addingComment) {
      //deleting the comment
      node.comment = null;
      deleteCurrentComment();
      return;
    }

    node.comment = NEW_COMMENT_TEXT;

    pgnStore.state.editingCommentNodeId = node.uid;
  }

  function setComment(comment: string | null) {
    const node = pgnStore.currentNode;
    if (node && pgnStore.state.currentGame) {
      node.comment = trimToNull(comment);
      console.debug('Setting dirty true');
      pgnStore.state.currentGame.isDirty = true;
    }
  }

  function deleteCurrentComment() {
    setComment(null);
  }

  function deleteCurrentVariation() {
    const game = pgnStore.state.currentGame;
    if (!game || !game.currentNode.parent) {
      return;
    }

    if (isMainline(game.currentNode)) {
      logger.warn('Cannot delete mainline moves');
      return;
    }

    const parent = game.currentNode.parent;
    const index = parent.children.indexOf(game.currentNode);
    if (index !== -1) {
      parent.children.splice(index, 1);
      game.currentNode = parent;
      console.debug('Setting dirty true');
      game.isDirty = true;
      pgnStore.state.selectedIndex = null;
      pgnStore.state.legalMoves = [];
    }
  }

  function promoteVariation() {
    const game = pgnStore.state.currentGame;
    if (!game || !game.currentNode.parent) {
      return;
    }

    if (promoteNode(game.currentNode)) {
      console.debug('Setting dirty true');
      game.isDirty = true;
    }

    //TODO
    //To fix the depth flags of everything, reparse the entire game
  }

  function toggleNag(nag: number) {
    const game = pgnStore.state.currentGame;
    if (game) {
      setNag(game.currentNode, nag);
      console.debug('Setting dirty true');
      game.isDirty = true;
    }
  }

  function setUserTitle(title: string) {
    const game = pgnStore.state.currentGame;
    if (!game) {
      return;
    }

    if (title.trim()) {
      game.headers.set('UserTitle', title);
    } else {
      game.headers.delete('UserTitle');
    }
    game.dbEntry.userTitle = title.trim() || undefined;
    console.debug('Setting dirty true');
    game.isDirty = true;
  }

  function selectSquare(index: number) {
    const game = pgnStore.state.currentGame;
    if (!game) {
      return;
    }

    const existingMove = pgnStore.state.legalMoves.find((lm) => lm.to_square_index === index);
    if (pgnStore.state.selectedIndex !== null && existingMove) {
      makeMove(existingMove.uci);
      return;
    }

    pgnStore.state.selectedIndex = null;
    pgnStore.state.legalMoves = [];

    const board = pgnStore.currentBoard;
    const piece = board[index];
    if (!piece || piece.color !== pgnStore.currentTurn) {
      return;
    }

    pgnStore.state.selectedIndex = index;
    const chess = new Chess(pgnStore.currentFen);
    const moves = chess.moves({
      square: indexToUci(index),
      verbose: true,
    });

    for (const move of moves) {
      pgnStore.state.legalMoves.push({
        from_square_index: index,
        to_square_index: uciToIndex(move.to),
        uci: indexToUci(index) + move.to + (move.promotion ? move.promotion : ''),
      });
    }
  }

  function makeMove(uci: string) {
    const game = pgnStore.state.currentGame;
    if (!game) {
      return;
    }

    const newNode = addMove(game, uci);
    if (!newNode) {
      return;
    }
    console.debug('Setting dirty true');
    game.isDirty = true;
    pgnStore.state.selectedIndex = null;
    pgnStore.state.legalMoves = [];
  }

  function goToNode(node: PgnNode) {
    const game = pgnStore.state.currentGame;
    if (!game) {
      return;
    }
    game.currentNode = node;
    pgnStore.state.selectedIndex = null;
    pgnStore.state.legalMoves = [];
  }

  type AsyncFunction<Args extends any[], R> = (...args: Args) => Promise<R>;

  function onceAtATime<Args extends any[], R>(fn: AsyncFunction<Args, R>) {
    let running = false;

    return async function (...args: Args): Promise<R> {
      try {
        if (running) {
          console.log('Cancel || call');
        }
        running = true;
        return await fn(...args);
      } finally {
        running = false; // allow next execution
      }
    };
  }

  async function makeProblemImpl() {
    if (!pgnStore.currentNode) {
      return;
    }

    const parentNode = pgnStore.currentNode.parent;

    if (!parentNode) {
      return;
    }

    const currentGame = pgnStore.state.currentGame;

    if (!currentGame) {
      return;
    }

    snackbar.add({
      text: 'Creating problem',
      type: 'info',
      duration: 750,
    });

    //this will populate the evals in the nodes
    await engineStore.calculateDelta(parentNode, pgnStore.currentNode);

    //Should be on blunder move
    const newProblem: NewChessProblem = {
      fen: parentNode.fen,
      eval: parentNode.eval!.score,
      last_attempt: null,
      status: null,
      tags: [],
      blunder_move_san: pgnStore.currentNode.san,
      blunder_move_eval: pgnStore.currentNode.eval!.score,
      pgn_filename: pgnStore.currentPgnFilename,
      game_index: currentGame.dbEntry.gameIndex,
      pgn_tags: Object.fromEntries(currentGame.headers),
      initial_move_uci: pgnStore.currentNode.uci,
    };

    await chessDb.problems.add(newProblem as ChessProblem);
  }

  const makeProblem = onceAtATime(makeProblemImpl);

  return {
    makeProblem,
    toggleComment,
    toggleDelta,
    formatNag,
    deleteCurrentComment,
    setComment,
    canPromote,
    promoteVariation,
    toggleNag,
    deleteCurrentVariation,
    setUserTitle,
    goToNode,
    selectSquare,
  };
}
