import { usePgnStore } from '@/stores/pgn';
import { chessDb } from '@/stores/client_database';
import type {
  ChessProblem,
  DbPgnGame,
  NewChessProblem,
  NewPgnFile,
  PgnFile,
} from '@/stores/interfaces';
import { useLoggerStore } from '@/stores/logger';
import { parsePgn } from 'chessops/pgn';
import {
  addNewLines,
  createPgnGameFromChessops,
  generatePgn,
  isSafeInteger,
} from '@/util/pgn-tree';
import { splitPgnStream } from '@/stores/util/pgn_splitter';
import { getIntegerFromLocalStorage } from '@/stores/util/local_storage';
import { getApiBase, setApiBase } from '@/stores/problem';
import { useSnackbar } from 'vue3-snackbar';
import { getActiveColor } from '@/stores/util/fen';
import { ref } from 'vue';
import { State } from 'chess.ts';

export function usePgnIO() {
  const pgnStore = usePgnStore();
  const logger = useLoggerStore();
  const snackbar = useSnackbar();

  // State for API base configuration dialog
  const showApiBaseDialog = ref(false);
  let pendingOperation: (() => Promise<void>) | null = null;

  async function handleExport() {
    // Generate PGN for ALL games in the current file
    const pgn = await generateFullPgn(pgnStore.state.currentPgnFile);
    if (!pgn) {
      return;
    }

    const blob = new Blob([pgn], { type: 'text/plain' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = pgnStore.currentPgnFilename || 'game.pgn';
    a.click();
    URL.revokeObjectURL(url);
  }

  function handleImport(event: Event) {
    const file = (event.target as HTMLInputElement).files?.[0];
    if (!file) {
      return;
    }

    const reader = new FileReader();
    reader.onload = async (e) => {
      const content = e.target?.result as string;

      // Check for existing pgn with same filename
      const existing = await chessDb.getPgnByFilename(file.name);
      if (existing) {
        window.alert(`File "${file.name}" already exists`);
        return;
      }

      const pgnFile: NewPgnFile = {
        filename: file.name,
        lastModified: file.lastModified,
        content: content,
        dirty: false,
        server_md5: 'imported',
      };

      const pgnFileId = await chessDb.storePgn(pgnFile);

      // Refresh store from IndexedDB
      await loadPgnFiles();

      //will have id
      const pgnFileState = pgnStore.state.allPgnFiles.find((f) => f.id === pgnFileId);
      if (pgnFileState) {
        await loadPgnFile(pgnFileState);
      }

      if (pgnStore.state.games.length > 0) {
        await loadGame(pgnStore.state.games[0]!);
      }
    };
    reader.readAsText(file);
  }

  async function handleCopyCurrentGame() {
    const game = pgnStore.state.currentGame;
    if (!game) {
      return;
    }

    try {
      const pgn = pgnStore.generatePgn(game);
      await navigator.clipboard.writeText(pgn);
      logger.info('Game PGN copied to clipboard 📋');
    } catch (err: unknown) {
      const msg = err instanceof Error ? err.message : String(err);
      logger.error('Failed to copy PGN: ' + msg);
    }
  }

  async function importGameFromPastedText() {
    if (!pgnStore.state.currentPgnFile) {
      logger.error('No PGN file selected');
      return;
    }

    try {
      const text = await navigator.clipboard.readText();
      if (!text || !text.trim()) {
        logger.warn('Clipboard is empty');
        return;
      }

      const parsedGames = Array.from(splitPgnStream(text));
      if (parsedGames.length === 0) {
        logger.error('No valid games found in clipboard content');
        return;
      }

      let addedCount = 0;
      for (const pgnContent of parsedGames) {
        await chessDb.addGameToPgn({
          fileId: pgnStore.state.currentPgnFile.id,
          content: pgnContent,
        });
        addedCount++;
      }

      if (addedCount > 0) {
        pgnStore.state.games = await chessDb.getGames(pgnStore.state.currentPgnFile.id);
        //refresh dirty flag which was set by addGameToPgn
        await refreshPgnFile();

        if (!pgnStore.state.currentGame && pgnStore.state.games.length > 0) {
          await loadGame(pgnStore.state.games[0]!);
        }
      }

      snackbar.add({ text: `Imported ${addedCount} game(s) from clipboard`, type: 'success' });
    } catch (err: unknown) {
      const msg = err instanceof Error ? err.message : String(err);
      logger.error('Failed to import from clipboard: ' + msg);
    }
  }

  async function refreshPgnFile() {
    if (!pgnStore.state.currentPgnFile) {
      return;
    }
    //See loadPgnFiles
    pgnStore.state.currentPgnFile = await chessDb.getPgnById(pgnStore.state.currentPgnFile.id);

    pgnStore.state.allPgnFiles = await chessDb.getAllPgns();
  }

  async function deleteGame(game: DbPgnGame) {
    if (!pgnStore.state.currentPgnFile || pgnStore.state.currentPgnFile.id !== game.fileId) {
      logger.error('Game does not belong to current file');
      return;
    }

    if (!confirm(`Delete game ${game.title || '#' + game.gameIndex}?`)) {
      return;
    }

    try {
      await chessDb.deletePgnGame(game.fileId, game.gameIndex);

      // Update local state by refetching
      pgnStore.state.games = await chessDb.getGames(game.fileId);

      await refreshPgnFile();

      // If we deleted the current game, unload it
      if (pgnStore.state.currentGame?.dbEntry.gameIndex === game.gameIndex) {
        pgnStore.state.currentGame = null;
        pgnStore.state.selectedIndex = null;
        pgnStore.state.legalMoves = [];
      }
    } catch (e) {
      logger.error(`Failed to delete game: ${e}`);
    }
  }

  async function loadPgnFiles() {
    const pgns = await chessDb.getAllPgns();
    pgnStore.state.allPgnFiles = pgns;

    // Restore selection from localStorage
    const savedPgnId = getIntegerFromLocalStorage('currentPgnId');

    if (savedPgnId != null) {
      const toLoad = pgnStore.state.allPgnFiles.find((f) => f.id == savedPgnId) ?? null;
      if (toLoad) {
        await loadPgnFile(toLoad);
      }
    }

    if (!pgnStore.state.currentPgnFile && pgns.length > 0) {
      await loadPgnFile(pgns[0]!);
    }
  }

  async function loadPgnFile(pgnFile: PgnFile | null) {
    if (!pgnFile || !isSafeInteger(pgnFile.id)) {
      logger.warn(`pgn file no games or falsy`);
      pgnStore.state.games = [];
      pgnStore.state.currentGame = null;

      pgnStore.state.selectedIndex = null;
      pgnStore.state.legalMoves = [];
      pgnStore.state.currentPgnFile = null;
      return;
    }

    pgnStore.state.currentPgnFile = pgnFile;

    localStorage.setItem('currentPgnId', pgnStore.state.currentPgnFile.id.toString());

    const savedGameIndex = getIntegerFromLocalStorage('currentGameIndex');

    const games = await chessDb.getGames(pgnStore.state.currentPgnFile.id);

    pgnStore.state.games = games;
    pgnStore.state.currentGame = null;

    if (savedGameIndex !== null && savedGameIndex < pgnStore.state.games.length) {
      const game = pgnStore.state.games.find((g) => g.gameIndex == savedGameIndex);
      if (game) {
        await loadGame(game);
        return;
      }
    }

    if (pgnStore.state.games.length > 0) {
      await loadGame(pgnStore.state.games[0]!);
    }
  }

  async function loadGame(dbGame: DbPgnGame) {
    if (
      !dbGame ||
      dbGame.fileId !== pgnStore.state.currentPgnFile?.id ||
      !Number.isSafeInteger(dbGame.fileId)
    ) {
      throw new Error(`db game id inconsistent`);
    }

    const parsedPgnReturn = parsePgn(dbGame.content);
    if (parsedPgnReturn.length != 1) {
      throw new Error(
        `Expected exactly 1 game ${parsedPgnReturn.length} for game index ${dbGame.gameIndex}`,
      );
    }
    logger.info(`Loading game pgnFileId: ${dbGame.fileId} #${dbGame.gameIndex}`);
    pgnStore.state.currentGame = createPgnGameFromChessops(parsedPgnReturn[0]!, dbGame);

    const restoredNode = pgnStore.restoreCurrentNode();

    localStorage.setItem(
      'currentGameIndex',
      pgnStore.state.currentGame.dbEntry.gameIndex.toString(),
    );

    if (!restoredNode) {
      pgnStore.state.currentGame.currentNode = pgnStore.state.currentGame.root;
    }
    localStorage.removeItem('currentPgnNodePath');
  }

  async function deletePgnById(id: number): Promise<boolean> {
    const pgn = await chessDb.getPgnById(id);

    if (!confirm(`Are you sure you want to delete ${pgn.filename} id ${pgn.id}?`)) {
      return false;
    }

    try {
      await chessDb.deletePgn(id);
      pgnStore.state.allPgnFiles = await chessDb.getAllPgns();
      if (pgnStore.state.currentPgnFile?.id === id) {
        await loadPgnFile(pgnStore.state.allPgnFiles[0] || null);
      }
      snackbar.add({
        type: 'info',
        text: `Deleted PGN file id ${id} ${pgn.filename}`,
      });
      return true;
    } catch (err: unknown) {
      const msg = err instanceof Error ? err.message : String(err);
      snackbar.add({
        type: 'error',
        text: 'Failed to delete PGN: ' + msg,
      });
      return false;
    }
  }

  async function saveCurrentGame() {
    const file = pgnStore.state.currentPgnFile;
    if (!file) {
      logger.error('No file selected for saving');
      return;
    }

    if (!pgnStore.state.currentGame) {
      throw new Error(`no current game`);
    }

    try {
      const pgnContent = generatePgn(pgnStore.state.currentGame);

      const dbPgnGame = pgnStore.state.currentGame.dbEntry;
      dbPgnGame.lastModified = Date.now();
      dbPgnGame.content = pgnContent;

      await chessDb.updatePgnGame(dbPgnGame);

      //also done in chessDb, could also refresh from id
      file.dirty = true;

      pgnStore.state.currentGame.isDirty = false;

      logger.info(`Saved PGN file: ${file.filename}`);
    } catch (err: unknown) {
      const msg = err instanceof Error ? err.message : String(err);
      logger.error(`Failed to save PGN "${file.filename}": ${msg}`);
      throw err;
    }
  }

  async function generateFullPgn(pgnFile: PgnFile | null): Promise<string | null> {
    if (!pgnFile) {
      return null;
    }

    if (!pgnFile.dirty) {
      logger.info(`Current file not dirty, exporting as is`);
      return pgnFile.content;
    }

    logger.info(`Concatenating games again`);
    const games = await chessDb.getGames(pgnFile.id);

    const pgnContent = games.map((g) => addNewLines(g.content)).join('\n\n');

    pgnFile.content = pgnContent;
    pgnFile.lastModified = Date.now();
    pgnFile.dirty = false;
    await chessDb.updatePgn(pgnFile);

    return pgnContent;
  }

  async function uploadAll() {
    try {
      for (const pgnFile of pgnStore.state.allPgnFiles) {
        const pgn = await generateFullPgn(pgnFile);

        const fileName = pgnFile.filename;

        const encodedFilename = encodeURIComponent(fileName);

        const response = await fetch(`${getApiBase()}/upload?filename=${encodedFilename}`, {
          method: 'PUT',
          headers: {
            'Content-Type': 'application/x-chess-pgn',
          },
          body: pgn,
        });

        const responseJson = await response.json();

        if (response.status != 200) {
          snackbar.add({
            type: 'warning',
            text: `${fileName} failed ${responseJson['detail']}`,
          });
        } else {
          snackbar.add({
            type: 'success',
            text: `${fileName} uploaded`,
          });
        }

        logger.info(`Response`, responseJson);
      }

      //Now do problems
      const problems = await chessDb.problems.toArray();

      const jsonProblems = JSON.stringify({ problems }, null, 4);

      const response = await fetch(
        `${getApiBase()}/upload?filename=${encodeURIComponent('problems.json')}`,
        {
          method: 'PUT',
          headers: {
            'Content-Type': 'application/json',
          },
          body: jsonProblems,
        },
      );

      const responseJson = await response.json();

      if (response.status != 200) {
        snackbar.add({
          type: 'warning',
          text: `Problems upload failed ${responseJson['detail']}`,
        });
      } else {
        snackbar.add({
          type: 'success',
          text: `Problems uploaded`,
        });
      }

      logger.info(`Problem Response`, responseJson);
    } catch (error) {
      logger.error('Upload failed:', error);
      snackbar.add({
        type: 'error',
        text: 'Upload failed. Please check API server configuration.',
      });
      // Store the operation for retry
      pendingOperation = uploadAll;
      showApiBaseDialog.value = true;
    }
  }

  async function downloadAll() {
    try {
      const res = await fetch(`${getApiBase()}/download`);

      if (!res.ok) {
        throw new Error(`HTTP error! status: ${res.status}`);
      }

      const reader = res.body!.getReader();
      const decoder = new TextDecoder();

      let buffer = '';

      let pgnNotModified = 0;
      let pgnServerCount = 0;

      while (true) {
        const { done, value } = await reader.read();
        if (done) {
          break;
        }

        buffer += decoder.decode(value, { stream: true });
        const lines = buffer.split('\n');
        buffer = lines.pop()!; // incomplete line

        for (const line of lines) {
          if (!line.trim()) {
            continue;
          }
          const msg: { name: string; content: string; lastModified: number; md5: string } =
            JSON.parse(line);

          if (msg.name.endsWith('.json')) {
            const problemList: Array<ChessProblem> = JSON.parse(msg.content)['problems'];

            //do some cleaning
            // const cleanedProblems: Array<ChessProblem> = [];

            for (const [probIdx, prob] of problemList.entries()) {
              //reindex
              prob.id = 1 + probIdx;

              //delete (prob as Partial<ChessProblem>).id;
              //   // if (isString(prob.last_attempt)) {
              //   //   const d = new Date(prob.last_attempt);
              //   //   prob.last_attempt = d.getTime();
              //   // }
              //   // if (prob.blunder_move_eval > 2) {
              //   //   continue;
              //   // }
              //   // if (prob.eval < 0.3) {
              //   //   continue;
              //   // }
              //   const isBlack = getActiveColor(prob.fen);
              //   if (isBlack == 'w') {
              //     prob.blunder_move_eval *= -1;
              //     prob.eval *= -1;
              //   }
              //   cleanedProblems.push(prob);
            }

            if (confirm(`Replace problems with ${problemList.length} from server?`)) {
              await chessDb.problems.clear();
              await chessDb.storeProblems(problemList);
              //await updateProblemCount();
            }
            continue;
          }

          pgnServerCount += 1;
          const pgnFileMatch = pgnStore.state.allPgnFiles.find((f) => f.filename == msg.name);

          if (pgnFileMatch) {
            if (pgnFileMatch.server_md5 == msg.md5) {
              console.info(`Pgn file ${msg.name} not modified.  ${msg.md5}`);
              pgnNotModified += 1;
              continue;
            } else {
              console.info(
                `Pgn file ${msg.name} modified.  ${msg.md5} vs ${pgnFileMatch.server_md5}`,
              );
            }

            const deleted = await deletePgnById(pgnFileMatch.id);

            if (!deleted) {
              continue;
            }
          }

          const pgnFile: NewPgnFile = {
            filename: msg.name,
            lastModified: msg.lastModified,
            content: msg.content,
            dirty: false,
            server_md5: msg.md5,
          };

          await chessDb.storePgn(pgnFile);
          snackbar.add({
            type: 'info',
            text: `Stored pgn file ${pgnFile.filename}`,
          });

          console.log(msg);
        }
      }

      snackbar.add({
        type: 'info',
        text: `Not modified ${pgnNotModified}.  On Server ${pgnServerCount}`,
        duration: 30000,
      });
      // Refresh store from IndexedDB
      await loadPgnFiles();
    } catch (error) {
      logger.error('Download failed:', error);
      snackbar.add({
        type: 'error',
        text: 'Download failed. Please check API server configuration.',
      });
      // Store the operation for retry
      pendingOperation = downloadAll;
      showApiBaseDialog.value = true;
    }
  }

  async function retryWithNewApiBase(newBase: string) {
    setApiBase(newBase);
    if (pendingOperation) {
      await pendingOperation();
      pendingOperation = null;
    }
  }

  async function createEmptyPgnFile(filename: string): Promise<boolean> {
    if (!filename || !filename.trim()) {
      snackbar.add({
        type: 'error',
        text: 'Filename cannot be empty',
      });
      return false;
    }

    const trimmedFilename = filename.trim();

    // Check for existing pgn with same filename
    const existing = await chessDb.getPgnByFilename(trimmedFilename);
    if (existing) {
      snackbar.add({
        type: 'error',
        text: `File "${trimmedFilename}" already exists`,
      });
      return false;
    }

    try {
      const pgnFile: NewPgnFile = {
        filename: trimmedFilename,
        lastModified: Date.now(),
        content: '',
        dirty: false,
        server_md5: 'new',
      };

      const pgnFileId = await chessDb.storePgn(pgnFile);

      // Refresh store from IndexedDB
      await loadPgnFiles();

      // Load the newly created file
      const pgnFileState = pgnStore.state.allPgnFiles.find((f) => f.id === pgnFileId);
      if (pgnFileState) {
        await loadPgnFile(pgnFileState);
      }

      snackbar.add({
        type: 'success',
        text: `Created PGN file: ${trimmedFilename}`,
      });

      return true;
    } catch (err: unknown) {
      const msg = err instanceof Error ? err.message : String(err);
      snackbar.add({
        type: 'error',
        text: `Failed to create PGN file: ${msg}`,
      });
      return false;
    }
  }

  async function renamePgnFile(fileId: number, newFilename: string): Promise<boolean> {
    if (!newFilename || !newFilename.trim()) {
      snackbar.add({
        type: 'error',
        text: 'Filename cannot be empty',
      });
      return false;
    }

    const trimmedFilename = newFilename.trim();

    try {
      const pgnFile = await chessDb.getPgnById(fileId);

      // Check if filename is different
      if (pgnFile.filename === trimmedFilename) {
        return true; // No change needed
      }

      // Check for existing pgn with same filename
      const existing = await chessDb.getPgnByFilename(trimmedFilename);
      if (existing && existing.id !== fileId) {
        snackbar.add({
          type: 'error',
          text: `File "${trimmedFilename}" already exists`,
        });
        return false;
      }

      pgnFile.filename = trimmedFilename;
      await chessDb.updatePgn(pgnFile);

      // Refresh store from IndexedDB
      await loadPgnFiles();

      // Update current file reference if it's the one being renamed
      if (pgnStore.state.currentPgnFile?.id === fileId) {
        pgnStore.state.currentPgnFile = await chessDb.getPgnById(fileId);
      }

      snackbar.add({
        type: 'success',
        text: `Renamed to: ${trimmedFilename}`,
      });

      return true;
    } catch (err: unknown) {
      const msg = err instanceof Error ? err.message : String(err);
      snackbar.add({
        type: 'error',
        text: `Failed to rename PGN file: ${msg}`,
      });
      return false;
    }
  }

  return {
    importGameFromPastedText,
    deleteGame,
    handleExport,
    handleImport,
    handleCopyCurrentGame,
    loadPgnFiles,
    loadGame,
    loadPgnFile,
    deletePgnById,
    saveCurrentGame,
    generateFullPgn,
    uploadAll,
    downloadAll,
    showApiBaseDialog,
    retryWithNewApiBase,
    createEmptyPgnFile,
    renamePgnFile,
  };
}
