<script setup lang="ts">
  import { useEngineStore } from '@/stores/engineStore';
  import { useLoggerStore } from '@/stores/logger';
  import { usePgnStore } from '@/stores/pgn';
  import ChessBoard, { type BoardArrow } from '@/components/ChessBoard.vue';

  import { uciToIndex } from '@/stores/util/uci';
  import { computed, onMounted, onUnmounted } from 'vue';
  import MobileHeader from '@pgnMobile/MobileHeader.vue';
  import MobileFooter from '@/components/pgn_mobile/MobileFooter.vue';

  import PgnGameListTab from '@pgn/tabs/PgnGameListTab.vue';
  import PgnFileListTab from '@pgn/tabs/PgnFileListTab.vue';
  import PgnAnalysisTab from '@pgn/tabs/PgnAnalysisTab.vue';
  import PgnCommentsTab from '@pgn/tabs/PgnCommentsTab.vue';
  import MobileMoves from '@pgnMobile/MobileMoves.vue';
  import { useMobilePgnStore } from '@/stores/mobilePgn';
  import { usePgnIO } from '@/composables/pgnIO';
  import { usePgnEdit } from '@/composables/pgnEdit';

  const pgnStore = usePgnStore();
  const engineStore = useEngineStore();
  const logger = useLoggerStore();
  const mobilePgn = useMobilePgnStore();

  const { loadPgnFiles } = usePgnIO();
  const { selectSquare } = usePgnEdit();

  logger.info('Load mobile logger');
  //dry
  const boardArrows = computed<BoardArrow[]>(() => {
    return engineStore.state.analysisResults
      .filter((line) => line.uciMove && line.uciMove !== '(none)')
      .map((line) => ({
        from: uciToIndex(line.uciMove.substring(0, 2)),
        to: uciToIndex(line.uciMove.substring(2, 4)),
        opacity: Math.max(0.2, 1 - (line.multipv - 1) * 0.3),
      }));
  });

  onMounted(async () => {
    await loadPgnFiles();
  });

  onUnmounted(() => {
    engineStore.stopAnalysis();
  });
</script>

<template>
  <div class="page">
    <MobileHeader class="header" />

    <div class="board-wrapper">
      <ChessBoard
        :board="pgnStore.currentBoard"
        :fen="pgnStore.currentFen"
        :is-flipped="pgnStore.state.isFlipped"
        :selected-index="pgnStore.state.selectedIndex"
        :legal-moves="pgnStore.state.legalMoves"
        :arrows="boardArrows"
        @square-click="selectSquare"
      />
    </div>

    <!-- Tabs -->
    <div class="tabs-content">
      <!-- <PgnVariationsTab v-if="mobilePgn.state.activeTab === 'variations'" />
        <PgnCommentsTab v-if="activeTab === 'comments'" />
         -->
      <PgnCommentsTab v-if="mobilePgn.state.activeTab === 'Comments'" />
      <MobileMoves v-if="mobilePgn.state.activeTab === 'Moves'" />
      <PgnAnalysisTab v-if="mobilePgn.state.activeTab === 'Analysis'" />
      <PgnGameListTab v-if="mobilePgn.state.activeTab === 'Game List'" />
      <PgnFileListTab v-if="mobilePgn.state.activeTab === 'PGN Files'" />
    </div>

    <MobileFooter class="footer" />
  </div>
</template>

