<script setup lang="ts">
  import { watch } from 'vue';
  import { usePgnStore } from '@/stores/pgn';
  import { useEngineStore } from '@/stores/engineStore';
  import { useRoute } from 'vue-router';
  import MobileAnalysisPopup from '@/components/pgn_mobile/MobileAnalysisPopup.vue';

  const pgnStore = usePgnStore();
  const engineStore = useEngineStore();

  const route = useRoute();

  const isMobile = route.path == '/pgn-mobile';
  // Current path
  console.log(`Route ${route.path} ${isMobile}`); // e.g., "/pgn"

  // Re-run analysis when position changes if already analyzing
  watch(
    () => pgnStore.currentFen,
    () => {
      if (engineStore.state.isAnalyzing) {
        engineStore.startAnalysis();
      }
    },
  );

  function formatScore(score: number) {
    if (Math.abs(score) >= 9000) {
      // Mate score: 10000 - distance
      const distance = 10000 - Math.abs(score);
      const sign = score > 0 ? '+' : '-';
      return `#${sign}${distance}`;
    }
    const s = score;
    return s > 0 ? `+${s.toFixed(1)}` : s.toFixed(1);
  }
</script>

<template>
  <div class="pgn-analysis-tab">
    <MobileAnalysisPopup v-if="!isMobile || !engineStore.state.isAnalyzing" />

    <div class="analysis-results">
      <div
        v-if="engineStore.state.analysisResults.length === 0 && engineStore.state.isAnalyzing"
        class="loading-state"
      >
        Thinking...
      </div>

      <div
        v-for="line in engineStore.state.analysisResults"
        :key="line.multipv"
        class="analysis-line"
      >
        <span class="rank">{{ line.multipv }}</span>
        <span
          class="score"
          :class="{ positive: line.score > 0, negative: line.score < 0 }"
        >
          {{ formatScore(line.score) }}
        </span>

        <span class="move">{{ line.san || line.uciMove }}</span>
        <span class="depth">Depth: {{ line.depth }} {{ line.seldepth }}</span>
      </div>
    </div>
  </div>
</template>

