/**
 * Efficient streaming PGN splitter
 * Yields each game as a string
 */

export function* splitPgnStream(pgn: string): Generator<string> {
  const len: number = pgn.length;

  //state variables
  let lookingForEndQuote = false;
  let foundMoves = false;

  //looking for ]
  let lookingForClosingBracket = false;

  // looking for }
  let lookingForClosingBrace = false;
  let firstOpeningBracketPos = -1;

  for (let i = 0; i < len; ++i) {
    const char: string = pgn[i]!;

    //quotes can contain [ ]
    if (lookingForEndQuote) {
      if (char == '"') {
        lookingForEndQuote = false;
      }
      continue;
    }

    if (char == '"') {
      lookingForEndQuote = true;
      continue;
    }

    //because { } can contain [ ] tags
    if (lookingForClosingBrace) {
      if (char == '}') {
        lookingForClosingBrace = false;
      }
      continue;
    }

    if (char == '{') {
      lookingForClosingBrace = true;
      continue;
    }

    if (char == '[') {
      //console.log(`[ found at ${i} foundMoves: ${foundMoves}`);
      lookingForClosingBracket = true;

      if (foundMoves) {
        yield pgn.substring(firstOpeningBracketPos, i - 1);
        foundMoves = false;
        firstOpeningBracketPos = -1;
      }

      //assume each game has at least 1 tag [ ]
      if (firstOpeningBracketPos == -1) {
        firstOpeningBracketPos = i;
      }

      continue;
    }

    if (lookingForClosingBracket) {
      if (char == ']') {
        lookingForClosingBracket = false;
      }
      continue;
    }

    if (char == '1') {
      foundMoves = true;
    }
  }

  if (firstOpeningBracketPos > -1) {
    // flush last game
    yield pgn.substring(firstOpeningBracketPos);
  }
}
