import { defineStore } from 'pinia';
import { reactive, watch } from 'vue';
import type {
  BoardState,
  ChessProblem,
  Color,
  HistoryEntry,
  LegalMove,
  Move,
  Piece,
  Status,
  Tag,
} from './interfaces';
import { fenToBoard, getActiveColor } from './util/fen';
import { calculateNextFen, indexToUci, uciToIndex } from './util/uci';
import { calculateMissingPieces, type MissingPiecesResult } from './util/material';
import { StockfishEngineWrapper } from '@/stores/util/load_engine';
import { Chess } from 'chess.ts';
import { useLoggerStore } from './logger';

import { chessDb } from './client_database';
import { getSan } from '@/util/pgn-tree';

export const useChessStore = defineStore('chess', () => {
  const logger = useLoggerStore();

  // Game state
  const game = reactive({
    board: Array<Piece | null>(64).fill(null) as BoardState,
    fen: '',
    turn: 'w' as Color,
    isFlipped: false,

    //In point of view of white
    currentEval: 0,

    history: [] as HistoryEntry[],
    missingPieces: {
      white: [] as string[],
      black: [] as string[],
      pointDisparity: 0,
    } as MissingPiecesResult,
    isAnalyze: false,
  });

  // Problem metadata
  const problem: ChessProblem = reactive({
    id: -1,
    status: null as Status | null,
    tags: [] as Tag[],
    last_attempt: null as number | null,
    blunder_move_san: '',
    //In whites point of view
    blunder_move_eval: 0,
    //In whites point of view
    eval: 0,
    pgn_filename: '',
    game_index: -1,
    pgn_tags: {} as Record<string, string>,
    fen: '',
    initial_move_uci: '',
  });

  // UI / interaction state
  const ui = reactive({
    selectedIndex: null as number | null,
    legalMoves: [] as LegalMove[],
    hint: null as Move | null,

    lastMove: null as Move | null,

    indexDbProblemCount: -1,
    filteredDbProblemCount: -1,
    filteredAttemptedDbProblemCount: -1,
    bestMoveAnalysis: [] as Array<string>,
  });

  // Settings (persisted)
  const settings = reactive({
    engineTime: Number(localStorage.getItem('engineTime')) || 1.2,

    newProblemId: Number(localStorage.getItem('newProblemId')) || null,
  });

  logger.info(`Loading stockfish wrapper`);
  const stockfishEngine = new StockfishEngineWrapper(logger);
  logger.info(`Loading stockfish wrapper done`);

  /** Persist settings */
  watch(
    () => ({ ...settings }),
    (val) => {
      localStorage.setItem('engineTime', val.engineTime.toString());

      localStorage.setItem(
        'newProblemId',
        Number.isSafeInteger(val.newProblemId) ? val.newProblemId!.toString() : '',
      );
    },
    { deep: true },
  );

  //MissingPiecesResult
  // Watch for changes to fen
  watch(
    () => game.fen,
    (newFen) => {
      game.missingPieces = calculateMissingPieces(newFen);
    },
    { immediate: true }, // calculate immediately for initial fen
  );

  stockfishEngine.thinking$.subscribe((thinking) => {
    const san = getSan(thinking.uciMove, game.fen);

    const score = Math.round(thinking.score * 10) / 10;
    ui.bestMoveAnalysis[thinking.multipv - 1] =
      `${thinking.multipv}: ${san} ${score * (game.isFlipped ? -1 : 1)}`;

    if (thinking.multipv == 1) {
      //not flipped, stay in persective of white
      game.currentEval = score;
    }
  });

  // Initialize
  fetchNextProblem();

  updateProblemCount().then();

  async function updateProblemCount() {
    const pc = await chessDb.getProblemCount();
    const filterProblems = await chessDb.getFilteredProblems();
    //const solved = await getProblemCountByStatus('solved');

    ui.indexDbProblemCount = pc;
    ui.filteredDbProblemCount = filterProblems.length;

    ui.filteredAttemptedDbProblemCount = filterProblems.filter(
      (p) => p.last_attempt != null,
    ).length;
  }

  async function fetchNextProblem(explicitProblemId: number | null = null) {
    //logger.log(`fetch next problem ${explicitProblemId}`);
    try {
      const data = await (async () => {
        if (Number.isSafeInteger(explicitProblemId) && explicitProblemId !== null) {
          return await chessDb.getProblemById(explicitProblemId);
        } else {
          return await chessDb.getNextProblem();
        }
      })();

      if (!data) {
        return null;
      }

      game.fen = data.fen;
      problem.id = data.id;

      if (explicitProblemId === null) {
        logger.log(`Adding ${problem.id} to history`);
        await chessDb.addToHistory(problem.id);
      }

      problem.last_attempt = data.last_attempt;

      game.board = fenToBoard(game.fen);
      game.turn = getActiveColor(game.fen);
      game.isFlipped = game.turn === 'b';

      problem.status = data.status;
      problem.tags = data.tags;
      problem.blunder_move_san = data.blunder_move_san;
      problem.blunder_move_eval = data.blunder_move_eval;
      problem.pgn_filename = data.pgn_filename;
      problem.game_index = data.game_index;
      problem.pgn_tags = data.pgn_tags;

      problem.eval = data.eval;
      game.currentEval = problem.eval;

      game.history = [];
      ui.hint = null;
      ui.lastMove = null;

      if (data.initial_move_uci) {
        ui.lastMove = {
          from: uciToIndex(data.initial_move_uci.slice(0, 2)),
          to: uciToIndex(data.initial_move_uci.slice(2, 4)),
        };
      } else {
        ui.lastMove = null;
      }
    } catch (error) {
      logger.error('Failed to fetch board:', error);
    }
  }

  async function selectSquare(index: number) {
    const existingMove = ui.legalMoves.find((lm) => lm.to_square_index === index);
    if (ui.selectedIndex !== null && existingMove) {
      await movePiece(existingMove);
      return;
    }

    ui.selectedIndex = null;
    ui.legalMoves = [];

    const piece = game.board[index];
    if (!piece || piece.color !== game.turn) {
      return;
    }

    ui.selectedIndex = index;

    const board = new Chess(game.fen);

    for (const move of board.moves({
      square: indexToUci(index),
      verbose: true,
    })) {
      // logger.log(move);
      ui.legalMoves.push({
        from_square_index: index,
        to_square_index: uciToIndex(move.to),
        uci: indexToUci(index) + move.to + (move.promotion ? move.promotion : ''),
      });
    }

    //logger.log(`legal moves ${JSON.stringify(ui.legalMoves)}`);
  }

  async function fetchHint() {
    const bestMoveUci = await stockfishEngine.calculateBestMove(game.fen, settings.engineTime);

    //logger.log(`Best move ${bestMoveUci.uci}`);
    ui.hint = {
      from: uciToIndex(bestMoveUci.uci.slice(0, 2)),
      to: uciToIndex(bestMoveUci.uci.slice(2, 4)),
    };
  }

  async function movePiece(legalMove: LegalMove) {
    const piece = game.board[legalMove.from_square_index];
    if (!piece) {
      throw new Error(`Piece expected @ [${legalMove}]`);
    }

    //apply legal move

    ui.selectedIndex = null;
    ui.legalMoves = [];
    ui.hint = null;
    ui.bestMoveAnalysis = ['-'];

    game.history.push({
      fen: game.fen,
      eval: game.currentEval,
      lastMove: ui.lastMove,
    });

    ui.lastMove = {
      from: legalMove.from_square_index,
      to: legalMove.to_square_index,
    };

    //logger.log(`Move piece`);

    const fen_after_user = calculateNextFen(game.fen, legalMove.uci);

    game.fen = fen_after_user;
    game.board = fenToBoard(game.fen);

    if (game.isAnalyze) {
      game.turn = getActiveColor(game.fen);
      startAnalyze();
      return;
    }

    await doEngineResponse();
  }

  async function doEngineResponse() {
    const bestMove = await stockfishEngine.calculateBestMove(game.fen, settings.engineTime);

    if (bestMove.uci == '(none)') {
      logger.info('Engine is check mated');
      return;
    }

    const fen_after_engine = calculateNextFen(game.fen, bestMove.uci);

    //We want undo to be before the last human move
    /*
    game.history.push({
      fen: game.fen,
      eval: game.currentEval,
      lastMove: ui.lastMove,
    });
    */

    //in perspective of white
    console.info(`Setting problem best move to ${bestMove.score}`);
    game.currentEval = bestMove.score;

    game.fen = fen_after_engine;
    ui.lastMove = {
      from: uciToIndex(bestMove.uci.substring(0, 2)),
      to: uciToIndex(bestMove.uci.substring(2, 4)),
    };
    game.board = fenToBoard(game.fen);
  }

  function undoMove() {
    if (game.history.length === 0) {
      return;
    }
    const prevState = game.history.pop()!;
    game.fen = prevState.fen;
    game.currentEval = prevState.eval;
    ui.lastMove = prevState.lastMove;

    game.board = fenToBoard(prevState.fen);

    game.turn = getActiveColor(game.fen);

    ui.selectedIndex = null;
    ui.legalMoves = [];
    ui.hint = null;
    ui.bestMoveAnalysis = ['-'];

    if (game.isAnalyze) {
      game.turn = getActiveColor(game.fen);
      startAnalyze();
    }
  }

  function toggleFlip() {
    game.isFlipped = !game.isFlipped;
  }

  async function copyFEN() {
    await navigator.clipboard.writeText(game.fen);
  }

  async function updateProblemTags(newTags: Array<Tag>) {
    logger.log(`update problem tags problem ${problem.id} tags ${newTags.join(', ')}`);
    if (problem.id === -1) {
      return;
    }
    try {
      const dbProblem = await chessDb.getProblemById(problem.id);
      if (!dbProblem) {
        throw new Error(`no index db problem found with index [${problem.id}]`);
      }
      dbProblem.tags = newTags;

      await chessDb.updateProblem(dbProblem);

      problem.tags = newTags;
    } catch (error) {
      logger.error('Failed to update problem metadata:', error);
    }
  }

  async function updateProblemStatus(newStatus: Status) {
    if (problem.id === -1) {
      return;
    }
    try {
      logger.log(`Update problem status to ${newStatus} `);

      const dbProblem = await chessDb.getProblemById(problem.id);
      if (!dbProblem) {
        throw new Error(`no index db problem found with index [${problem.id}]`);
      }
      dbProblem.status = newStatus;
      dbProblem.last_attempt = new Date().getTime();
      await chessDb.updateProblem(dbProblem);

      await updateProblemCount();

      await fetchNextProblem();
    } catch (error) {
      logger.error('Failed to update problem metadata:', error);
    }
  }

  function clearLastMove() {
    ui.lastMove = null;
  }

  async function loadIndexDb() {
    try {
      logger.log('Loading problems');
      const response = await fetch(`${getApiBase()}/problems`);

      if (!response.ok) {
        throw new Error(`HTTP error! status: ${response.status}`);
      }

      const data = await response.json();

      logger.log(`From api ${data.length} problems`);

      await chessDb.storeProblems(data);

      logger.log(` now updating problem count`);

      await updateProblemCount();
    } catch (error) {
      logger.error('Failed to load problems from API:', error);
      throw error; // Re-throw so calling code can handle it
    }
  }

  function startAnalyze() {
    game.isAnalyze = true;
    ui.bestMoveAnalysis = ['-'];
    stockfishEngine.infiniteCalc(game.fen);
  }
  function stopAnalyze() {
    game.isAnalyze = false;
    stockfishEngine.stopOngoingOperation();

    ui.bestMoveAnalysis = ['-'];
  }

  async function getHistory(): Promise<Array<ChessProblem>> {
    return await chessDb.getHistory();
  }

  const retVal = {
    // state
    game,
    problem,
    ui,
    settings,

    // actions
    copyFEN,
    selectSquare,
    movePiece,
    undoMove,
    updateProblemStatus,
    updateProblemTags,
    updateProblemCount,
    fetchNextProblem,
    fetchHint,
    clearLastMove,
    toggleFlip,
    loadIndexDb,

    startAnalyze,
    stopAnalyze,
    getHistory,
  };

  return retVal;
});

export function getApiBase(): string {
  // First check for user-configured API base
  const userApiBase = localStorage.getItem('apiBase');
  if (userApiBase) {
    return userApiBase;
  }

  // Fall back to environment variable
  const apiUrlOverride = import.meta.env.VITE_API_URL;
  if (apiUrlOverride) {
    return apiUrlOverride + '/api';
  }

  // Final fallback
  return 'api';
}

export function setApiBase(url: string): void {
  // Save to local storage
  localStorage.setItem('apiBase', url);

  // Update history (keep last 4 unique values)
  const history = getApiBaseHistory();
  
  // Remove the URL if it already exists to avoid duplicates
  const filtered = history.filter(h => h !== url);
  
  // Add the new URL to the front
  filtered.unshift(url);
  
  // Keep only the last 4
  const updated = filtered.slice(0, 4);
  
  localStorage.setItem('apiBaseHistory', JSON.stringify(updated));
}

export function getApiBaseHistory(): string[] {
  try {
    const history = localStorage.getItem('apiBaseHistory');
    if (history) {
      return JSON.parse(history);
    }
  } catch (e) {
    console.error('Failed to parse API base history', e);
  }
  return [];
}
